const STATS_KEY = 'dsf.combat.stats.v1';
const COMBO_WINDOW = 1.25;
const MIN_DAMAGE_SCALE = 0.45;

function damageScaleAtHit(hitNumber) {
  if (hitNumber <= 1) return 1;
  return Math.max(MIN_DAMAGE_SCALE, 0.94 - (hitNumber - 2) * 0.08);
}

function loadCareerStats(storage) {
  const fallback = { bestCombo: 0, sRanks: 0, matchesGraded: 0 };
  try {
    return { ...fallback, ...JSON.parse(storage?.getItem(STATS_KEY) || '{}') };
  } catch {
    return fallback;
  }
}

export class CombatPerformance {
  constructor({ storage = globalThis.localStorage } = {}) {
    this.storage = storage;
    this.career = loadCareerStats(storage);
    this.resetMatch();
  }

  resetMatch() {
    this.chains = [this._newChain(), this._newChain()];
    this.stats = [this._newStats(), this._newStats()];
    this._roundMinHpRatio = [1, 1];
    this._finished = false;
  }

  _newChain() {
    return { hits: 0, damage: 0, timer: 0 };
  }

  _newStats() {
    return {
      totalHits: 0,
      totalDamage: 0,
      maxCombo: 0,
      counters: 0,
      punishes: 0,
      superFinishes: 0,
      perfectRounds: 0,
      comebacks: 0,
    };
  }

  update(dt, fighters = []) {
    for (const chain of this.chains) {
      if (chain.timer <= 0) continue;
      chain.timer = Math.max(0, chain.timer - dt);
      if (chain.timer <= 0) {
        chain.hits = 0;
        chain.damage = 0;
      }
    }
    for (let i = 0; i < 2; i++) {
      const fighter = fighters[i];
      if (!fighter?.maxHp) continue;
      this._roundMinHpRatio[i] = Math.min(
        this._roundMinHpRatio[i],
        Math.max(0, fighter.hp / fighter.maxHp),
      );
    }
  }

  endChains() {
    for (const chain of this.chains) Object.assign(chain, this._newChain());
  }

  getDamageScale(attackerIdx, hitsInMove = 1) {
    const chain = this.chains[attackerIdx] ?? this._newChain();
    const incomingHits = Math.max(1, Math.round(hitsInMove));
    let total = 0;
    for (let i = 1; i <= incomingHits; i++) {
      total += damageScaleAtHit(chain.hits + i);
    }
    return total / incomingHits;
  }

  recordHit({ attackerIdx, damage, blocked, counter = false, punish = false, isSuper = false, isKO = false, hits = 1 }) {
    const defenderIdx = attackerIdx === 0 ? 1 : 0;
    Object.assign(this.chains[defenderIdx], this._newChain());
    if (blocked || damage <= 0) {
      Object.assign(this.chains[attackerIdx], this._newChain());
      return { ...this.chains[attackerIdx], scale: 1 };
    }

    const chain = this.chains[attackerIdx];
    const addedHits = Math.max(1, Math.round(hits));
    chain.hits += addedHits;
    chain.damage += Math.max(0, Math.round(damage));
    chain.timer = COMBO_WINDOW;

    const stats = this.stats[attackerIdx];
    stats.totalHits += addedHits;
    stats.totalDamage += Math.max(0, Math.round(damage));
    stats.maxCombo = Math.max(stats.maxCombo, chain.hits);
    if (counter) stats.counters += 1;
    if (punish) stats.punishes += 1;
    if (isSuper && isKO) stats.superFinishes += 1;

    return { ...chain };
  }

  recordRoundEnd({ winnerIdx, fighters }) {
    if (winnerIdx >= 0) {
      const winner = fighters[winnerIdx];
      const hpRatio = winner?.maxHp ? winner.hp / winner.maxHp : 0;
      if (hpRatio >= 0.999) this.stats[winnerIdx].perfectRounds += 1;
      if (this._roundMinHpRatio[winnerIdx] <= 0.2) this.stats[winnerIdx].comebacks += 1;
    }
    this._roundMinHpRatio = [1, 1];
    this.endChains();
  }

  finish({ playerIdx = 0, playerWon = false, roundsWon = 0 } = {}) {
    const stats = { ...this.stats[playerIdx] };
    const score = Math.round(
      (playerWon ? 350 : 90) +
      roundsWon * 80 +
      Math.min(280, stats.maxCombo * 35) +
      Math.min(150, stats.totalDamage * 0.12) +
      stats.counters * 30 +
      stats.punishes * 40 +
      stats.superFinishes * 80 +
      stats.perfectRounds * 90 +
      stats.comebacks * 70
    );
    const grade = score >= 850 ? 'S' : score >= 650 ? 'A' : score >= 450 ? 'B' : score >= 250 ? 'C' : 'D';
    const comboCoins = Math.min(50, Math.max(0, stats.maxCombo - 1) * 5);
    const counterCoins = Math.min(36, stats.counters * 4 + stats.punishes * 6);
    const coins = Math.round(
      (playerWon ? 50 : 20) + comboCoins + counterCoins +
      stats.superFinishes * 30 + stats.perfectRounds * 25 + stats.comebacks * 25
    );
    const xp = Math.round((playerWon ? 75 : 35) + score / 10);
    const result = { ...stats, score, grade, coins, xp };

    if (!this._finished) {
      this._finished = true;
      this.career.bestCombo = Math.max(this.career.bestCombo, stats.maxCombo);
      this.career.matchesGraded += 1;
      if (grade === 'S') this.career.sRanks += 1;
      try { this.storage?.setItem(STATS_KEY, JSON.stringify(this.career)); } catch { /* best effort */ }
    }
    return { ...result, careerBestCombo: this.career.bestCombo };
  }

  chain(side) {
    return { ...(this.chains[side] ?? this._newChain()) };
  }
}

export { COMBO_WINDOW, damageScaleAtHit };
