/** A side-view frame that keeps both combatants visible in the live viewport. */
export function fightCameraFrame(fighters, aspect, fovDegrees, options = {}) {
  const points = fighters.filter((fighter) => Number.isFinite(fighter?.position?.x));
  if (!points.length) return { x: 0, y: 1.2, distance: 7.5 };

  const left = Math.min(...points.map((fighter) => fighter.position.x));
  const right = Math.max(...points.map((fighter) => fighter.position.x));
  const top = Math.max(...points.map((fighter) => (fighter.position.y || 0) + 2.05));
  const centerX = (left + right) / 2;
  const centerY = Math.max(1.15, Math.min(1.85, top / 2));
  const halfWidth = Math.max(centerX - left, right - centerX) + (options.horizontalMargin ?? 0.95);
  const halfHeight = Math.max(centerY + 0.25, top - centerY + 0.3);
  const tangent = Math.tan((fovDegrees * Math.PI / 180) / 2);
  const safeAspect = Math.max(0.5, aspect || 1);
  const horizontalDistance = halfWidth / (tangent * safeAspect * 0.88);
  const verticalDistance = halfHeight / (tangent * 0.7);
  return {
    x: centerX,
    y: centerY,
    distance: Math.max(options.minDistance ?? 6.7, horizontalDistance, verticalDistance),
  };
}

export function minimumDistanceForFighters(fighters, lookX, aspect, fovDegrees, margin = 0.95, lookY = 1.2) {
  const points = fighters.filter((fighter) => Number.isFinite(fighter?.position?.x));
  if (!points.length) return 0;
  const furthest = Math.max(...points.map((fighter) => Math.abs(fighter.position.x - lookX)));
  const tangent = Math.tan((fovDegrees * Math.PI / 180) / 2);
  const horizontal = (furthest + margin) / (tangent * Math.max(0.5, aspect || 1) * 0.88);
  const vertical = Math.max(...points.map((fighter) => Math.max(
    Math.abs((fighter.position.y || 0) - lookY) + 0.25,
    Math.abs((fighter.position.y || 0) + 2.05 - lookY) + 0.25,
  ))) / (tangent * 0.7);
  return Math.max(horizontal, vertical);
}
