/**
 * MainMenu
 * --------
 * Title screen with clear mode navigation. Built as DOM and mounted inside
 * #ui-root so Windows Store reviewers land on an obvious playable surface.
 */

export class MainMenu {
  /** @param {HTMLElement} root */
  constructor(root, opts = {}) {
    this.root = root;
    this.branding = opts.branding ?? { displayName: 'Desi Street Brawler' };
  }

  show({ onQuickFight, onChampionship, onTraining, onDaily, onStory, onHowToPlay, dailySummary = {} } = {}) {
    this.hide();

    const wrap = document.createElement('div');
    wrap.className = 'dsf-main-menu';
    wrap.style.cssText = `
      position:absolute; inset:0;
      pointer-events:auto;
      z-index:60;
      display:grid;
      grid-template-columns:minmax(0, 1fr);
      place-items:center;
      overflow:auto;
      padding: max(12px, env(safe-area-inset-top)) max(12px, env(safe-area-inset-right))
        max(12px, env(safe-area-inset-bottom)) max(12px, env(safe-area-inset-left));
      background:
        linear-gradient(180deg, rgba(12,7,4,0.72), rgba(32,14,8,0.90)),
        radial-gradient(circle at 50% 22%, rgba(255,215,112,0.16), transparent 34%);
      color:#f5e9c9;
      font-family:'Segoe UI', system-ui, sans-serif;
    `;
    this._wrap = wrap;

    const responsiveStyles = document.createElement('style');
    responsiveStyles.textContent = `
      .dsf-main-menu__panel {
        width: min(1080px, calc(100vw - 24px));
        min-width: 0;
        max-width: 100%;
        max-height: calc(100dvh - 24px);
        overflow: auto;
        padding: clamp(16px, 2.4vw, 28px);
      }
      .dsf-main-menu__title { font-size: clamp(32px, 5vw, 58px); }
      .dsf-main-menu__actions {
        display: grid;
        grid-template-columns: repeat(6, minmax(0, 1fr));
        gap: 12px;
      }
      .dsf-main-menu__action {
        grid-column: span 2;
        min-height: 104px;
      }
      .dsf-main-menu__action:nth-child(n + 4) { grid-column: span 3; }
      @media (max-width: 760px) {
        .dsf-main-menu__actions { grid-template-columns: repeat(2, minmax(0, 1fr)); }
        .dsf-main-menu__action,
        .dsf-main-menu__action:nth-child(n + 4) { grid-column: span 1; }
        .dsf-main-menu__action:last-child { grid-column: span 2; }
      }
      @media (orientation: landscape) and (max-height: 600px) {
        .dsf-main-menu { place-items: stretch center !important; }
        .dsf-main-menu__panel {
          align-self: center;
          padding: 12px 14px !important;
          max-height: calc(100dvh - 16px);
        }
        .dsf-main-menu__title { font-size: clamp(27px, 5.5vh, 36px) !important; }
        .dsf-main-menu__subtitle {
          margin: 6px auto 10px !important;
          font-size: clamp(10px, 2.2vh, 13px) !important;
          line-height: 1.25 !important;
        }
        .dsf-main-menu__actions { gap: 8px; }
        .dsf-main-menu__action {
          min-height: 72px !important;
          padding: 9px 11px !important;
        }
        .dsf-main-menu__action-title { font-size: 13px !important; }
        .dsf-main-menu__action-detail {
          margin-top: 4px !important;
          font-size: 10px !important;
          line-height: 1.2 !important;
        }
        .dsf-main-menu__footer {
          margin-top: 8px !important;
          font-size: 9px !important;
        }
      }
      @media (max-width: 560px) and (orientation: portrait) {
        .dsf-main-menu__actions { grid-template-columns: 1fr; }
        .dsf-main-menu__action,
        .dsf-main-menu__action:nth-child(n + 4),
        .dsf-main-menu__action:last-child { grid-column: span 1; }
      }
    `;
    wrap.appendChild(responsiveStyles);

    const panel = document.createElement('section');
    panel.className = 'dsf-main-menu__panel';
    panel.style.cssText = `
      border:2px solid #c79b3a;
      border-radius:8px;
      background:rgba(20,12,6,0.82);
      box-shadow:0 18px 48px rgba(0,0,0,0.55), inset 0 0 0 1px rgba(255,215,112,0.14);
      text-align:center;
    `;
    wrap.appendChild(panel);

    const title = document.createElement('h1');
    title.className = 'dsf-main-menu__title';
    title.textContent = this.branding.displayName;
    title.style.cssText = `
      margin:0;
      line-height:0.95;
      letter-spacing:0.08em;
      text-transform:uppercase;
      color:#ffd770;
      text-shadow:3px 3px 0 #1b120a, 0 0 28px rgba(255,215,112,0.55);
    `;
    panel.appendChild(title);

    const subtitle = document.createElement('p');
    subtitle.className = 'dsf-main-menu__subtitle';
    subtitle.textContent = 'Fight best-of-3 matches, climb the championship ladder, and prove your fighter is street champion.';
    subtitle.style.cssText = `
      margin:14px auto 22px;
      max-width:640px;
      font-size:clamp(13px, 2.5vw, 17px);
      line-height:1.45;
      color:rgba(245,233,201,0.86);
    `;
    panel.appendChild(subtitle);

    const actions = document.createElement('div');
    actions.className = 'dsf-main-menu__actions';
    panel.appendChild(actions);

    const makeButton = (label, detail, handler, primary = false) => {
      const button = document.createElement('button');
      button.type = 'button';
      button.className = 'dsf-main-menu__action';
      button.style.cssText = `
        min-height:104px;
        padding:16px 14px;
        border:2px solid ${primary ? '#ffd770' : '#8d6421'};
        border-radius:8px;
        background:${primary ? 'linear-gradient(180deg, #7a2c16, #4a1810)' : 'rgba(42,18,10,0.92)'};
        color:#ffd770;
        cursor:pointer;
        font-family:inherit;
        text-align:left;
        box-shadow:${primary ? '0 0 22px rgba(255,215,112,0.32)' : 'none'};
      `;
      button.innerHTML = `
        <span class="dsf-main-menu__action-title" style="display:block;font-size:16px;font-weight:900;letter-spacing:0.12em;text-transform:uppercase;">${label}</span>
        <span class="dsf-main-menu__action-detail" style="display:block;margin-top:8px;font-size:12px;line-height:1.35;color:rgba(245,233,201,0.78);">${detail}</span>
      `;
      button.addEventListener('click', () => handler?.());
      actions.appendChild(button);
    };

    makeButton('Quick Fight', 'Pick two fighters and a stage for a complete best-of-3 match.', onQuickFight, true);
    makeButton('Championship', 'Choose one fighter and defeat the full ladder across multiple stages.', onChampionship);
    makeButton('Training', 'Learn Bilal through five rewarded combo trials with live timing feedback.', onTraining);
    const dailyAlerts = (dailySummary.claimable ?? 0) + (dailySummary.loginReady ? 1 : 0);
    makeButton(
      `Daily Rewards${dailyAlerts ? ` · ${dailyAlerts} READY` : ''}`,
      `${dailySummary.completed ?? 0}/3 missions claimed today. Maintain your seven-day login streak.`,
      onDaily,
      dailyAlerts > 0,
    );
    makeButton('How To Play', 'Controls, win rules, and match flow for keyboard, touch, and gamepad.', onHowToPlay);
    makeButton('Story', 'Meet the fighters and read the street circuit chapters. Videos are optional.', onStory);

    const footer = document.createElement('div');
    footer.className = 'dsf-main-menu__footer';
    footer.textContent = 'Every fight is first to 2 round wins. Use Esc or the pause button during battle.';
    footer.style.cssText = `
      margin-top:18px;
      font-size:12px;
      letter-spacing:0.08em;
      color:rgba(245,233,201,0.62);
      text-transform:uppercase;
    `;
    panel.appendChild(footer);

    this.root.appendChild(wrap);
  }

  hide() {
    if (this._wrap?.parentNode) this._wrap.parentNode.removeChild(this._wrap);
    this._wrap = null;
  }
}
