/** A specific, achievable reason to play the next match. */
export function nextMatchChallenge(performance) {
  if (!performance) return null;
  if (performance.totalHits === 0) return 'NEXT GOAL  Land one clean hit';
  if (performance.maxCombo < 3) return 'NEXT GOAL  Land a 3 hit combo';
  if ((performance.punishes ?? 0) < 1) return 'NEXT GOAL  Punish one missed attack';
  if (performance.grade !== 'S') return 'NEXT GOAL  Earn an S rank';
  return 'NEXT GOAL  Win with a different fighter';
}
