import { stageMusicTheme } from './StageMusic.js';

/**
 * Clean, lightweight fight audio made entirely with Web Audio.
 *
 * The game does not ship third-party samples, so these cues use layered,
 * filtered noise and damped resonators to imitate body impacts, cloth, wood,
 * metal and drums. A compressor and a short room response keep rapid combos
 * warm and controlled instead of becoming sharp or painfully loud.
 */

export const SUPPORTED_MOVE_SOUNDS = Object.freeze([
  'sfx_hit_light',
  'sfx_hit_medium',
  'sfx_hit_heavy',
  'sfx_throw',
  'sfx_shoryuken',
  'sfx_abdullah_gandasa',
  'sfx_abdullah_lalkaar',
  'sfx_abdullah_super',
  'sfx_toofan_dash',
  'sfx_toofan_grab',
  'sfx_toofan_super',
  'sfx_bilal_reverse',
  'sfx_bilal_cyclone',
  'sfx_bilal_super',
  'sfx_pehalwan_charge',
  'sfx_pehalwan_grab',
  'sfx_pehalwan_super',
]);

const GENERIC_HITS = new Set([
  'sfx_hit_light',
  'sfx_hit_medium',
  'sfx_hit_heavy',
]);

const HIT_SAMPLES = Object.freeze({
  light: ['hit_light_01', 'hit_light_02', 'hit_light_03'],
  medium: ['hit_medium_01', 'hit_medium_02', 'hit_medium_03'],
  heavy: ['hit_heavy_01', 'hit_heavy_02', 'hit_heavy_03'],
});

const BLOCK_SAMPLES = Object.freeze(['block_01', 'block_02', 'block_03']);
const JUMP_SAMPLES = Object.freeze(['jump_01', 'jump_02']);
const KO_SAMPLES = Object.freeze(['ko_01', 'ko_02']);
const CHARACTER_CUE_PRIORITY = Object.freeze({
  reaction: 1,
  taunt: 2,
  intro: 3,
  special: 4,
  victory: 5,
});

const MOVE_SAMPLES = Object.freeze({
  sfx_throw: 'throw',
  sfx_shoryuken: 'shoryuken',
  sfx_abdullah_gandasa: 'abdullah_gandasa',
  sfx_abdullah_lalkaar: 'abdullah_lalkaar',
  sfx_abdullah_super: 'abdullah_super',
  sfx_toofan_dash: 'babu_dash',
  sfx_toofan_grab: 'babu_grab',
  sfx_toofan_super: 'babu_super',
  sfx_bilal_reverse: 'bilal_reverse',
  sfx_bilal_cyclone: 'bilal_cyclone',
  sfx_bilal_super: 'bilal_super',
  sfx_pehalwan_charge: 'pehalwan_charge',
  sfx_pehalwan_grab: 'pehalwan_grab',
  sfx_pehalwan_super: 'pehalwan_super',
});

export const CHARACTER_CUE_SAMPLE_IDS = Object.freeze(
  ['abdullah', 'babu', 'aslam', 'sher', 'irfan', 'hina', 'bilal', 'pehalwan']
    .flatMap((character) => ['intro', 'special', 'taunt', 'reaction', 'victory']
      .map((cueName) => `char_${character}_${cueName}`)),
);

const SAMPLE_IDS = Object.freeze([
  ...Object.values(HIT_SAMPLES).flat(),
  ...BLOCK_SAMPLES,
  ...JUMP_SAMPLES,
  ...KO_SAMPLES,
  'round_cue',
  ...Object.values(MOVE_SAMPLES),
  ...CHARACTER_CUE_SAMPLE_IDS,
]);

export const AUDIO_SAMPLE_FILES = Object.freeze(Object.fromEntries([
  ...SAMPLE_IDS.map((id) => [id, `/audio/sfx/${id}.wav`]),
  ['music_dhol_arena', '/audio/music/dhol_arena_loop.wav'],
]));

const APP_BASE = import.meta.env?.BASE_URL || '/';
function audioAssetUrl(path) {
  const base = APP_BASE.endsWith('/') ? APP_BASE : `${APP_BASE}/`;
  return `${base}${String(path).replace(/^\/+/, '')}`;
}

export class ProceduralAudio {
  constructor() {
    this.ctx = null;
    this.masterGain = null;
    this._musicGain = null;
    this._sfxGain = null;
    this._voiceGain = null;
    this._musicVolume = 0.28;
    this._activeVoiceSource = null;
    this._activeVoicePriority = 0;
    this._activeVoiceEndsAt = 0;
    this._dholRunning = false;
    this._dholTimer = null;
    this._stageMusicId = null;
    this._stageMusicStep = 0;
    this._stageMusicBar = 0;
    this._stageMusicNextTime = 0;
    this._noiseBuffers = new Map();
    this._samples = new Map();
    this._sampleCursor = new Map();
    this._preloadPromise = null;
    this._musicSource = null;

    try {
      const Ctor = window.AudioContext || window.webkitAudioContext;
      if (Ctor) this.ctx = new Ctor();
    } catch (_) {
      // Web Audio is optional. The game remains playable without it.
    }

    if (!this.ctx) return;

    this.masterGain = this.ctx.createGain();
    this.masterGain.gain.value = 0.55;

    const compressor = this.ctx.createDynamicsCompressor();
    compressor.threshold.value = -18;
    compressor.knee.value = 18;
    compressor.ratio.value = 4;
    compressor.attack.value = 0.004;
    compressor.release.value = 0.22;
    this.masterGain.connect(compressor);
    compressor.connect(this.ctx.destination);

    this._sfxGain = this.ctx.createGain();
    this._sfxGain.gain.value = 0.8;
    const sfxTone = this.ctx.createBiquadFilter();
    sfxTone.type = 'lowpass';
    sfxTone.frequency.value = 9800;
    sfxTone.Q.value = 0.35;
    this._sfxGain.connect(sfxTone);
    sfxTone.connect(this.masterGain);

    // Dialogue stays dry and forward in the mix. It has its own bus so the
    // Voice setting does not also alter punches, UI sounds, or music.
    this._voiceGain = this.ctx.createGain();
    this._voiceGain.gain.value = 0.8;
    const voiceCompressor = this.ctx.createDynamicsCompressor();
    voiceCompressor.threshold.value = -22;
    voiceCompressor.knee.value = 12;
    voiceCompressor.ratio.value = 3;
    voiceCompressor.attack.value = 0.006;
    voiceCompressor.release.value = 0.14;
    this._voiceGain.connect(voiceCompressor);
    voiceCompressor.connect(this.masterGain);

    this._musicGain = this.ctx.createGain();
    this._musicGain.gain.value = this._musicVolume;
    const musicTone = this.ctx.createBiquadFilter();
    musicTone.type = 'lowpass';
    musicTone.frequency.value = 7600;
    musicTone.Q.value = 0.25;
    this._musicGain.connect(musicTone);
    musicTone.connect(this.masterGain);

    // A short, dark room adds space without the metallic tail of a long reverb.
    const room = this.ctx.createConvolver();
    room.buffer = this._makeRoomImpulse(0.34, 3.6);
    const roomReturn = this.ctx.createGain();
    roomReturn.gain.value = 0.18;
    room.connect(roomReturn);
    roomReturn.connect(this.masterGain);

    const sfxRoomSend = this.ctx.createGain();
    sfxRoomSend.gain.value = 0.07;
    this._sfxGain.connect(sfxRoomSend);
    sfxRoomSend.connect(room);

    const musicRoomSend = this.ctx.createGain();
    musicRoomSend.gain.value = 0.15;
    this._musicGain.connect(musicRoomSend);
    musicRoomSend.connect(room);

    this._preloadPromise = this._preloadSamples();
  }

  resume() {
    if (this.ctx?.state === 'suspended') this.ctx.resume().catch(() => {});
  }

  setMasterVolume(value) { this._setGain(this.masterGain, value); }
  setMusicVolume(value) {
    this._musicVolume = Math.max(0, Math.min(1, Number(value) || 0));
    this._setGain(this._musicGain, this._musicVolume);
  }
  setSfxVolume(value) { this._setGain(this._sfxGain, value); }
  setVoiceVolume(value) { this._setGain(this._voiceGain, value); }

  /** A dry strike with a body, contact and cloth layer. */
  hit(tier = 'light', soundId = '') {
    if (!this.ctx) return;
    const variation = 0.96 + Math.random() * 0.08;
    const sampleId = this._nextSample(HIT_SAMPLES[tier] ?? HIT_SAMPLES.light);
    if (this._playSample(sampleId, { rate: variation, gain: tier === 'heavy' ? 1 : 0.92 })) {
      this.moveImpact(soundId);
      return;
    }
    const at = this.ctx.currentTime;

    if (tier === 'heavy') {
      this._tone({ at, start: 92 * variation, end: 43, duration: 0.23, gain: 0.42 });
      this._tone({ at: at + 0.006, start: 54, end: 38, duration: 0.28, gain: 0.16 });
      this._noise({ at, duration: 0.075, gain: 0.20, frequency: 1350, q: 0.72 });
      this._noise({ at: at + 0.012, duration: 0.12, gain: 0.09, frequency: 510, q: 0.6 });
    } else if (tier === 'medium') {
      this._tone({ at, start: 145 * variation, end: 67, duration: 0.15, gain: 0.34 });
      this._noise({ at, duration: 0.052, gain: 0.17, frequency: 1800, q: 0.8 });
      this._noise({ at: at + 0.008, duration: 0.085, gain: 0.07, frequency: 620, q: 0.65 });
    } else {
      this._tone({ at, start: 205 * variation, end: 105, duration: 0.095, gain: 0.25 });
      this._noise({ at, duration: 0.038, gain: 0.13, frequency: 2350, q: 0.9 });
      this._noise({ at: at + 0.005, duration: 0.055, gain: 0.05, frequency: 760, q: 0.7 });
    }

    this.moveImpact(soundId, at);
  }

  /** Muted guard contact with a brief, damped metal/bracelet ring. */
  block() {
    if (!this.ctx) return;
    if (this._playSample(this._nextSample(BLOCK_SAMPLES), { rate: 0.97 + Math.random() * 0.06, gain: 0.88 })) return;
    const at = this.ctx.currentTime;
    this._tone({ at, start: 132, end: 78, duration: 0.11, gain: 0.20 });
    this._noise({ at, duration: 0.045, gain: 0.13, frequency: 2400, q: 1.15 });
    this._resonance(720, 0.15, 0.045, at + 0.003, -0.12);
    this._resonance(1120, 0.11, 0.032, at + 0.004, 0.12);
  }

  /** Air and clothing movement, with no electronic whistle. */
  jump() {
    if (!this.ctx) return;
    if (this._playSample(this._nextSample(JUMP_SAMPLES), { rate: 0.97 + Math.random() * 0.05, gain: 0.72 })) return;
    this._whoosh(380, 1350, 0.16, 0.12, this.ctx.currentTime, -0.08);
  }

  /** Short, directional cue for a spawned chakra projectile. */
  projectileLaunch() {
    if (!this.ctx) return;
    const at = this.ctx.currentTime;
    this._whoosh(310, 1600, 0.18, 0.11, at, 0);
    this._tone({ at, start: 180, end: 105, duration: 0.16, gain: 0.11 });
  }

  /** A weighty fall and dust tail for a knockout. */
  ko() {
    if (!this.ctx) return;
    if (this._playSample(this._nextSample(KO_SAMPLES), { rate: 0.96 + Math.random() * 0.04, gain: 1.05 })) return;
    const at = this.ctx.currentTime;
    this._tone({ at, start: 72, end: 34, duration: 0.42, gain: 0.48 });
    this._noise({ at, duration: 0.11, gain: 0.22, frequency: 980, q: 0.62 });
    this._noise({ at: at + 0.07, duration: 0.42, gain: 0.09, frequency: 330, q: 0.45, kind: 'brown' });
    this._drum(64, 0.28, at + 0.11, 'sfx');
  }

  /**
   * Add a restrained material or movement accent for every move sound ID.
   * Generic normals already receive their complete sound in hit().
   */
  moveImpact(soundId = '', at = null) {
    if (!this.ctx || !soundId || GENERIC_HITS.has(soundId)) return;
    const designedSample = MOVE_SAMPLES[soundId];
    if (designedSample && this._playSample(designedSample, { gain: 0.82 })) return;
    const t = at ?? this.ctx.currentTime;

    switch (soundId) {
      case 'sfx_throw':
        this._noise({ at: t + 0.012, duration: 0.13, gain: 0.09, frequency: 470, q: 0.55, kind: 'brown' });
        this._tone({ at: t + 0.018, start: 84, end: 47, duration: 0.22, gain: 0.18 });
        break;
      case 'sfx_shoryuken':
        this._whoosh(330, 2350, 0.24, 0.12, t, 0.08);
        break;
      case 'sfx_abdullah_gandasa':
        this._whoosh(480, 2800, 0.21, 0.12, t, 0.14);
        this._resonance(940, 0.22, 0.035, t + 0.035, -0.08);
        this._resonance(1470, 0.16, 0.022, t + 0.038, 0.1);
        break;
      case 'sfx_abdullah_lalkaar':
        this._drum(76, 0.20, t + 0.015, 'sfx');
        this._noise({ at: t, duration: 0.18, gain: 0.06, frequency: 720, q: 1.35, kind: 'brown' });
        break;
      case 'sfx_abdullah_super':
        this._whoosh(310, 2400, 0.30, 0.14, t, 0.1);
        this._drum(60, 0.26, t + 0.08, 'sfx');
        this._resonance(820, 0.28, 0.035, t + 0.055);
        break;
      case 'sfx_toofan_dash':
        this._whoosh(270, 1280, 0.22, 0.11, t, -0.12);
        break;
      case 'sfx_toofan_grab':
        this._noise({ at: t, duration: 0.16, gain: 0.085, frequency: 560, q: 0.55, kind: 'brown' });
        this._tone({ at: t + 0.015, start: 98, end: 54, duration: 0.19, gain: 0.16 });
        break;
      case 'sfx_toofan_super':
        this._whoosh(260, 1700, 0.34, 0.13, t, -0.18);
        this._whoosh(420, 2300, 0.24, 0.09, t + 0.08, 0.18);
        this._drum(58, 0.22, t + 0.12, 'sfx');
        break;
      case 'sfx_bilal_reverse':
        this._whoosh(360, 2500, 0.23, 0.12, t, 0.1);
        this._resonance(610, 0.10, 0.024, t + 0.055);
        break;
      case 'sfx_bilal_cyclone':
        this._whoosh(760, 360, 0.25, 0.10, t, -0.38);
        this._whoosh(420, 1500, 0.23, 0.09, t + 0.035, 0.38);
        break;
      case 'sfx_bilal_super':
        // A wooden bat crack followed by a distant, soft stadium swell.
        this._noise({ at: t, duration: 0.028, gain: 0.21, frequency: 2500, q: 1.3 });
        this._resonance(690, 0.12, 0.052, t + 0.002, -0.05, 'triangle');
        this._resonance(1080, 0.08, 0.032, t + 0.003, 0.06, 'triangle');
        this._noise({ at: t + 0.07, duration: 0.48, gain: 0.048, frequency: 920, q: 0.42, kind: 'brown' });
        break;
      case 'sfx_pehalwan_charge':
        this._whoosh(250, 1150, 0.26, 0.12, t, -0.12);
        this._drum(62, 0.20, t + 0.08, 'sfx');
        break;
      case 'sfx_pehalwan_grab':
        this._tone({ at: t, start: 76, end: 35, duration: 0.32, gain: 0.27 });
        this._noise({ at: t + 0.02, duration: 0.24, gain: 0.10, frequency: 390, q: 0.48, kind: 'brown' });
        break;
      case 'sfx_pehalwan_super':
        this._drum(56, 0.28, t, 'sfx');
        this._drum(48, 0.32, t + 0.18, 'sfx');
        this._noise({ at: t + 0.12, duration: 0.46, gain: 0.11, frequency: 310, q: 0.44, kind: 'brown' });
        break;
      default:
        break;
    }
  }

  characterCue(soundId, { delay = 0, gain = 0.68, pan = 0 } = {}) {
    if (!CHARACTER_CUE_SAMPLE_IDS.includes(soundId)) return false;
    const cueName = soundId.split('_').at(-1);
    return this._playSample(soundId, {
      delay,
      gain,
      pan,
      channel: 'voice',
      exclusive: true,
      duckMusic: true,
      priority: CHARACTER_CUE_PRIORITY[cueName] ?? 1,
    });
  }

  /** Soft round cue used by the match flow. */
  roundCue() {
    if (!this.ctx) return;
    if (this._playSample('round_cue', { gain: 0.78 })) return;
    const at = this.ctx.currentTime;
    this._drum(74, 0.18, at, 'sfx');
    this._resonance(440, 0.34, 0.035, at + 0.025, -0.08, 'sine');
    this._resonance(660, 0.28, 0.026, at + 0.04, 0.08, 'sine');
  }

  /** Start the mastered dhol/tabla arena loop. Idempotent. */
  startDholLoop() {
    if (!this.ctx || this._dholRunning) return;
    this._dholRunning = true;
    if (this._stageMusicId) {
      this._startStageMusic();
      return;
    }
    if (this._startMusicSample()) return;
    this._preloadPromise?.then(() => {
      if (this._dholRunning && !this._stageMusicId) this._startMusicSample();
    });
  }

  /** Use the selected stage's original theme; null restores menu music. */
  setStageMusic(musicId) {
    if (this._stageMusicId === musicId) return;
    const wasRunning = this._dholRunning;
    this.stopDholLoop();
    this._stageMusicId = musicId;
    if (wasRunning && this._musicVolume > 0) this.startDholLoop();
  }

  stopDholLoop() {
    this._dholRunning = false;
    if (this._dholTimer) {
      clearInterval(this._dholTimer);
      this._dholTimer = null;
    }
    if (this._musicSource) {
      try { this._musicSource.stop(); } catch (_) { /* already stopped */ }
      this._musicSource = null;
    }
  }

  _startStageMusic() {
    if (this._dholTimer || !this.ctx) return;
    this._stageMusicStep = 0;
    this._stageMusicBar = 0;
    this._stageMusicNextTime = this.ctx.currentTime + 0.06;
    const schedule = () => {
      if (!this._dholRunning || !this._stageMusicId) return;
      const theme = stageMusicTheme(this._stageMusicId);
      const stepDuration = 60 / theme.bpm / 4;
      while (this._stageMusicNextTime < this.ctx.currentTime + 0.16) {
        this._playStageStep(theme, this._stageMusicStep, this._stageMusicNextTime);
        this._stageMusicStep = (this._stageMusicStep + 1) % 16;
        if (this._stageMusicStep === 0) this._stageMusicBar++;
        this._stageMusicNextTime += stepDuration;
      }
    };
    schedule();
    this._dholTimer = setInterval(schedule, 45);
  }

  _playStageStep(theme, step, at) {
    const root = theme.root + theme.harmony[this._stageMusicBar % theme.harmony.length];
    if (theme.kick.includes(step)) this._drum(64, 0.18, at, 'music');
    if (theme.snare.includes(step)) {
      this._noise({ at, duration: 0.09, gain: 0.075, frequency: 1550, channel: 'music' });
    }
    if (theme.dhol.includes(step)) this._tablaSlap(at, 0.055);
    if (step % 2 === 0) {
      this._noise({ at, duration: 0.025, gain: 0.018, frequency: 5500, channel: 'music' });
    }
    const bass = theme.bass[step];
    if (bass != null) {
      const frequency = 440 * 2 ** ((root + bass - 69) / 12);
      this._tone({ at, start: frequency, end: frequency * 0.994, duration: 0.22,
        gain: 0.095, type: 'triangle', channel: 'music', attack: 0.006 });
    }
    const lead = theme.lead[step];
    if (lead != null) {
      const frequency = 440 * 2 ** ((root + lead - 69) / 12);
      this._tone({ at, start: frequency, end: frequency * 0.997, duration: 0.14,
        gain: 0.032, type: 'sine', channel: 'music', attack: 0.012, pan: 0.12 });
    }
  }

  ready() {
    return this._preloadPromise ?? Promise.resolve();
  }

  async _preloadSamples() {
    const entries = Object.entries(AUDIO_SAMPLE_FILES)
      .map(([id, path]) => [id, audioAssetUrl(path)]);
    const failures = [];
    await Promise.all(entries.map(async ([id, url]) => {
      try {
        const response = await fetch(url);
        if (!response.ok) throw new Error(`${response.status} ${response.statusText}`);
        const bytes = await response.arrayBuffer();
        const decoded = await this.ctx.decodeAudioData(bytes.slice(0));
        this._samples.set(id, decoded);
      } catch (error) {
        failures.push(`${id}: ${error?.message ?? error}`);
      }
    }));
    if (failures.length) {
      console.warn(`[audio] ${failures.length} sample(s) unavailable; using synthesized fallbacks`, failures);
    }
  }

  _nextSample(pool) {
    if (!pool?.length) return '';
    const key = pool.join('|');
    const current = this._sampleCursor.has(key)
      ? this._sampleCursor.get(key)
      : Math.floor(Math.random() * pool.length);
    this._sampleCursor.set(key, (current + 1) % pool.length);
    return pool[current];
  }

  _playSample(id, {
    gain = 1,
    rate = 1,
    pan = 0,
    channel = 'sfx',
    delay = 0,
    exclusive = false,
    duckMusic = false,
    priority = 0,
  } = {}) {
    const buffer = this._samples.get(id);
    if (!buffer || !this.ctx) return false;
    if (exclusive && this._activeVoiceSource && this._activeVoiceEndsAt > this.ctx.currentTime) {
      if (priority < this._activeVoicePriority) return false;
      try { this._activeVoiceSource.stop(); } catch (_) { /* already stopped */ }
      this._activeVoiceSource = null;
    }
    const source = this.ctx.createBufferSource();
    source.buffer = buffer;
    source.playbackRate.value = Math.max(0.82, Math.min(1.18, rate));
    const amp = this.ctx.createGain();
    amp.gain.value = Math.max(0, Math.min(1.4, gain));
    source.connect(amp);
    this._route(amp, channel, pan);
    const startAt = this.ctx.currentTime + Math.max(0, delay);
    const duration = buffer.duration / source.playbackRate.value;
    if (exclusive) {
      this._activeVoiceSource = source;
      this._activeVoicePriority = priority;
      this._activeVoiceEndsAt = startAt + duration;
      source.onended = () => {
        if (this._activeVoiceSource === source) {
          this._activeVoiceSource = null;
          this._activeVoicePriority = 0;
          this._activeVoiceEndsAt = 0;
        }
      };
    }
    if (duckMusic) this._duckMusic(startAt, duration);
    source.start(startAt);
    return true;
  }

  _duckMusic(startAt, duration) {
    if (!this._musicGain || !this.ctx || this._musicVolume <= 0) return;
    const gain = this._musicGain.gain;
    const now = this.ctx.currentTime;
    const duckAt = Math.max(now, startAt);
    gain.cancelScheduledValues(now);
    gain.setValueAtTime(gain.value, now);
    gain.linearRampToValueAtTime(this._musicVolume * 0.28, duckAt + 0.055);
    gain.setValueAtTime(this._musicVolume * 0.28, duckAt + duration);
    gain.linearRampToValueAtTime(this._musicVolume, duckAt + duration + 0.2);
  }

  _startMusicSample() {
    if (this._musicSource || !this.ctx) return Boolean(this._musicSource);
    const buffer = this._samples.get('music_dhol_arena');
    if (!buffer) return false;
    const source = this.ctx.createBufferSource();
    source.buffer = buffer;
    source.loop = true;
    const amp = this.ctx.createGain();
    amp.gain.value = 0.68;
    source.connect(amp);
    this._route(amp, 'music');
    this._musicSource = source;
    source.onended = () => {
      if (this._musicSource === source) this._musicSource = null;
    };
    source.start();
    return true;
  }

  _setGain(node, value) {
    if (!node || !this.ctx) return;
    const safe = Math.max(0, Math.min(1, Number(value) || 0));
    node.gain.cancelScheduledValues(this.ctx.currentTime);
    node.gain.setTargetAtTime(safe, this.ctx.currentTime, 0.018);
  }

  _makeRoomImpulse(seconds, decay) {
    const length = Math.max(1, Math.floor(this.ctx.sampleRate * seconds));
    const impulse = this.ctx.createBuffer(2, length, this.ctx.sampleRate);
    for (let channel = 0; channel < impulse.numberOfChannels; channel++) {
      const data = impulse.getChannelData(channel);
      for (let i = 0; i < length; i++) {
        const envelope = Math.pow(1 - i / length, decay);
        data[i] = (Math.random() * 2 - 1) * envelope * 0.65;
      }
    }
    return impulse;
  }

  _noiseBuffer(kind = 'white') {
    if (this._noiseBuffers.has(kind)) return this._noiseBuffers.get(kind);
    const length = Math.floor(this.ctx.sampleRate * 2);
    const buffer = this.ctx.createBuffer(1, length, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);
    let brown = 0;
    for (let i = 0; i < length; i++) {
      const white = Math.random() * 2 - 1;
      if (kind === 'brown') {
        brown = (brown + 0.018 * white) / 1.018;
        data[i] = Math.max(-1, Math.min(1, brown * 3.2));
      } else {
        data[i] = white;
      }
    }
    this._noiseBuffers.set(kind, buffer);
    return buffer;
  }

  _route(node, channel = 'sfx', pan = 0) {
    const bus = channel === 'music'
      ? this._musicGain
      : channel === 'voice'
        ? this._voiceGain
        : this._sfxGain;
    if (!bus) return;
    if (this.ctx.createStereoPanner) {
      const panner = this.ctx.createStereoPanner();
      panner.pan.value = Math.max(-1, Math.min(1, pan));
      node.connect(panner);
      panner.connect(bus);
    } else {
      node.connect(bus);
    }
  }

  _envelope(gainNode, at, attack, duration, peak) {
    const end = at + Math.max(duration, attack + 0.008);
    gainNode.gain.setValueAtTime(0.0001, at);
    gainNode.gain.linearRampToValueAtTime(Math.max(0.0002, peak), at + attack);
    gainNode.gain.exponentialRampToValueAtTime(0.0001, end);
    return end;
  }

  _tone({ at, start, end, duration, gain, type = 'sine', channel = 'sfx', pan = 0, attack = 0.002 }) {
    const osc = this.ctx.createOscillator();
    osc.type = type;
    osc.frequency.setValueAtTime(Math.max(20, start), at);
    osc.frequency.exponentialRampToValueAtTime(Math.max(20, end), at + duration);
    const amp = this.ctx.createGain();
    const stop = this._envelope(amp, at, Math.min(attack, duration * 0.35), duration, gain);
    osc.connect(amp);
    this._route(amp, channel, pan);
    osc.start(at);
    osc.stop(stop + 0.01);
  }

  _noise({ at, duration, gain, frequency, q = 0.8, kind = 'white', channel = 'sfx', pan = 0 }) {
    const source = this.ctx.createBufferSource();
    source.buffer = this._noiseBuffer(kind);
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'bandpass';
    filter.frequency.value = frequency;
    filter.Q.value = q;
    const amp = this.ctx.createGain();
    const stop = this._envelope(amp, at, 0.0015, duration, gain);
    source.connect(filter);
    filter.connect(amp);
    this._route(amp, channel, pan);
    const available = Math.max(0, source.buffer.duration - duration - 0.01);
    source.start(at, Math.random() * available, duration);
    source.stop(stop + 0.01);
  }

  _whoosh(startFrequency, endFrequency, duration, gain, at, pan = 0) {
    const source = this.ctx.createBufferSource();
    source.buffer = this._noiseBuffer('brown');
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'bandpass';
    filter.frequency.setValueAtTime(startFrequency, at);
    filter.frequency.exponentialRampToValueAtTime(endFrequency, at + duration);
    filter.Q.value = 0.62;
    const amp = this.ctx.createGain();
    const stop = this._envelope(amp, at, duration * 0.28, duration, gain);
    source.connect(filter);
    filter.connect(amp);
    this._route(amp, 'sfx', pan);
    const available = Math.max(0, source.buffer.duration - duration - 0.01);
    source.start(at, Math.random() * available, duration);
    source.stop(stop + 0.01);
  }

  _resonance(frequency, duration, gain, at, pan = 0, type = 'sine') {
    this._tone({
      at,
      start: frequency * (1.005 + Math.random() * 0.008),
      end: frequency,
      duration,
      gain,
      type,
      pan,
      attack: 0.001,
    });
  }

  _drum(frequency, gain, at, channel) {
    this._tone({ at, start: frequency * 1.9, end: frequency * 0.72, duration: 0.18, gain, channel, attack: 0.0015 });
    this._noise({ at, duration: 0.026, gain: gain * 0.28, frequency: frequency * 6.2, q: 0.85, channel });
  }

  _tablaSlap(at, gain) {
    this._noise({ at, duration: 0.042, gain, frequency: 2050, q: 1.1, channel: 'music', pan: 0.12 });
    this._resonanceMusic(310, 0.08, gain * 0.48, at, -0.08);
  }

  _resonanceMusic(frequency, duration, gain, at, pan = 0) {
    this._tone({ at, start: frequency * 1.04, end: frequency, duration, gain, channel: 'music', pan, attack: 0.001 });
  }
}
