export function youtubeEmbedUrl(watchUrl, { autoplay = false } = {}) {
  try {
    const url = new URL(watchUrl);
    const host = url.hostname.toLowerCase();
    const id = host === 'youtu.be' ? url.pathname.slice(1)
      : ['youtube.com', 'www.youtube.com'].includes(host) && url.pathname === '/watch'
        ? url.searchParams.get('v') : null;
    if (url.protocol !== 'https:' || !/^[A-Za-z0-9_-]{11}$/.test(id ?? '')) return null;
    return `https://www.youtube.com/embed/${id}?playsinline=1&rel=0&autoplay=${autoplay ? 1 : 0}`;
  } catch { return null; }
}
