import { STORY_CHAPTERS, STORY_SCENES } from '../data/storyChapters.js';
import { youtubeEmbedUrl } from '../utils/youtubeEmbed.js';

const localStoryPreview = import.meta.env.MODE === 'story-qa';

export class StoryMenu {
  constructor(host, chapters = STORY_CHAPTERS) {
    this.host = host;
    this.chapters = chapters;
    this.root = null;
    this.previewOverlay = null;
    this.onPreviewKeyDown = null;
    this.chapterOverlay = null;
    this.onChapterKeyDown = null;
  }

  show({ onBack, onSkip } = {}) {
    this.hide();
    const root = document.createElement('section');
    root.className = 'dsf-story-menu';
    root.setAttribute('aria-label', 'Story chapters');
    root.style.cssText = 'position:absolute;inset:0;z-index:70;pointer-events:auto;overflow:auto;background:linear-gradient(160deg,#170b08,#352012);color:#f5e9c9;padding:clamp(12px,3vw,32px);font-family:Segoe UI,system-ui,sans-serif';
    const shell = document.createElement('div');
    shell.style.cssText = 'max-width:1040px;margin:auto';
    const head = document.createElement('header');
    head.style.cssText = 'display:flex;flex-wrap:wrap;gap:12px;align-items:center;justify-content:space-between;margin-bottom:16px';
    const title = document.createElement('div');
    title.innerHTML = `<h1 style="margin:0;color:#ffd770">Story</h1><p style="margin:5px 0;color:#dac8a9">Watch the story videos here, read the chapters, or skip straight to a fight.</p>`;
    head.appendChild(title);
    const nav = document.createElement('div');
    nav.style.cssText = 'display:flex;gap:8px;flex-wrap:wrap';
    const button = (label, action) => {
      const el = document.createElement('button');
      el.type = 'button'; el.textContent = label;
      el.style.cssText = 'border:1px solid #d4a743;border-radius:6px;background:#492416;color:#ffe3a0;padding:11px 16px;font:700 14px Segoe UI,system-ui;cursor:pointer';
      el.addEventListener('click', action); nav.appendChild(el);
    };
    button('Back', () => onBack?.());
    button('Skip Story · Fight', () => onSkip?.());
    head.appendChild(nav);
    shell.appendChild(head);
    for (const group of ['Fighter reveals', 'Main story']) {
      const label = document.createElement('h2'); label.textContent = group;
      label.style.cssText = 'color:#ffd770;border-bottom:1px solid #85601f;padding-bottom:6px;margin:24px 0 12px';
      shell.appendChild(label);
      const grid = document.createElement('div');
      grid.style.cssText = 'display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:10px';
      for (const chapter of this.chapters.filter((item) => item.group === group)) {
        const card = document.createElement('article');
        card.style.cssText = 'background:#27150e;border:1px solid #8d6421;border-radius:8px;padding:14px;min-height:142px;display:flex;flex-direction:column';
        const name = document.createElement('h3'); name.textContent = chapter.title;
        name.style.cssText = 'margin:0;color:#ffe097;font-size:17px';
        const blurb = document.createElement('p'); blurb.textContent = chapter.blurb;
        blurb.style.cssText = 'font-size:13px;line-height:1.35;color:#d5c6b2;flex:1';
        const watch = document.createElement('button');
        watch.type = 'button';
        const published = Boolean(youtubeEmbedUrl(chapter.youtubeUrl));
        const hasLocalPreview = localStoryPreview && Boolean(chapter.previewFile);
        const available = published || hasLocalPreview;
        watch.textContent = hasLocalPreview ? 'Preview cut ▶' : published ? 'Watch here ▶' : 'Coming soon';
        watch.disabled = !available;
        watch.style.cssText = `align-self:flex-start;padding:8px 11px;border-radius:5px;border:1px solid #c79b3a;background:${available ? '#78401d' : '#342b22'};color:#ffe0a0;cursor:${available ? 'pointer' : 'default'};opacity:${available ? 1 : 0.68}`;
        if (hasLocalPreview) watch.addEventListener('click', () => this.openPreview(chapter));
        else if (published) watch.addEventListener('click', () => this.openPreview(chapter, { published: true }));
        const read = document.createElement('button');
        read.type = 'button'; read.textContent = 'Read chapter';
        read.style.cssText = 'align-self:flex-start;padding:8px 11px;margin-bottom:8px;border-radius:5px;border:1px solid #d4a743;background:#78401d;color:#ffe0a0;cursor:pointer';
        read.addEventListener('click', () => this.openChapter(chapter));
        card.append(name, blurb, read);
        if (available) card.append(watch);
        grid.appendChild(card);
      }
      shell.appendChild(grid);
    }
    root.appendChild(shell); this.host.appendChild(root); this.root = root;
  }

  openChapter(chapter) {
    this.closeChapter();
    const overlay = document.createElement('div');
    overlay.className = 'dsf-story-chapter';
    overlay.setAttribute('role', 'dialog');
    overlay.setAttribute('aria-modal', 'true');
    overlay.setAttribute('aria-label', `${chapter.title} story`);
    overlay.style.cssText = 'position:fixed;inset:0;z-index:100;pointer-events:auto;background:#080504ed;display:flex;align-items:center;justify-content:center;padding:16px';
    const panel = document.createElement('div');
    panel.style.cssText = 'width:min(100%,620px);max-height:90vh;overflow:auto;background:#21110b;border:1px solid #d4a743;border-radius:10px;padding:clamp(18px,4vw,32px);color:#ffe4a8';
    const heading = document.createElement('h2');
    heading.textContent = chapter.title;
    heading.style.cssText = 'margin:0 0 16px;color:#ffd770';
    const scene = document.createElement('p');
    scene.textContent = STORY_SCENES[chapter.id] || chapter.blurb;
    scene.style.cssText = 'font-size:clamp(17px,2.4vw,21px);line-height:1.6';
    const close = document.createElement('button');
    close.type = 'button'; close.textContent = 'Close ×';
    close.style.cssText = 'border:1px solid #d4a743;border-radius:6px;background:#492416;color:#ffe3a0;padding:10px 18px;font:700 16px Segoe UI,system-ui;cursor:pointer';
    close.addEventListener('click', () => this.closeChapter());
    panel.append(heading, scene, close);
    overlay.appendChild(panel);
    overlay.addEventListener('click', (event) => { if (event.target === overlay) this.closeChapter(); });
    this.host.appendChild(overlay);
    this.chapterOverlay = overlay;
    this.onChapterKeyDown = (event) => {
      if (event.key === 'Escape') { event.stopImmediatePropagation(); this.closeChapter(); }
    };
    window.addEventListener('keydown', this.onChapterKeyDown, true);
    close.focus();
  }

  closeChapter() {
    this.chapterOverlay?.remove();
    this.chapterOverlay = null;
    if (this.onChapterKeyDown) window.removeEventListener('keydown', this.onChapterKeyDown, true);
    this.onChapterKeyDown = null;
  }

  openPreview(chapter, { published = false } = {}) {
    this.closePreview();
    const overlay = document.createElement('div');
    overlay.className = 'dsf-story-preview';
    overlay.setAttribute('role', 'dialog');
    overlay.setAttribute('aria-modal', 'true');
    overlay.setAttribute('aria-label', `${chapter.title} video preview`);
    overlay.style.cssText = 'position:fixed;inset:0;z-index:100;pointer-events:auto;background:#080504ed;display:flex;align-items:center;justify-content:center;padding:16px';
    const panel = document.createElement('div');
    panel.style.cssText = 'width:min(100%,960px);max-height:100%;overflow:auto;background:#21110b;border:1px solid #d4a743;border-radius:10px;padding:12px;color:#ffe4a8';
    const heading = document.createElement('div');
    heading.style.cssText = 'display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:10px';
    const name = document.createElement('strong');
    name.textContent = `${chapter.title} · ${published ? 'story video' : 'local review cut'}`;
    const close = document.createElement('button');
    close.type = 'button'; close.textContent = 'Close ×';
    close.style.cssText = 'border:1px solid #d4a743;border-radius:6px;background:#492416;color:#ffe3a0;padding:8px 12px;font:700 14px Segoe UI,system-ui;cursor:pointer';
    close.addEventListener('click', () => this.closePreview());
    heading.append(name, close);
    const video = document.createElement(published ? 'iframe' : 'video');
    if (published) {
      video.src = youtubeEmbedUrl(chapter.youtubeUrl, { autoplay: true });
      video.title = `${chapter.title} video`;
      video.allow = 'autoplay; encrypted-media; picture-in-picture; fullscreen';
      video.allowFullscreen = true;
      video.referrerPolicy = 'strict-origin-when-cross-origin';
      video.style.cssText = 'display:block;width:100%;height:min(65vh,540px);min-height:220px;border:0;background:#000';
    } else {
      video.controls = true;
      video.playsInline = true;
      video.preload = 'metadata';
      video.src = `${import.meta.env.MODE === 'story-qa' ? '/story-preview' : '/__story_preview'}/${chapter.previewFile}`;
      video.style.cssText = 'display:block;width:100%;max-height:min(75vh,600px);background:#000';
    }
    const error = document.createElement('p');
    error.style.cssText = 'display:none;color:#ff9b83';
    error.textContent = 'This local preview could not load. Check that the prepared video exists in output/story-video-review/production.';
    if (!published) video.addEventListener('error', () => { error.style.display = 'block'; });
    panel.append(heading, video, error);
    overlay.appendChild(panel);
    overlay.addEventListener('click', (event) => { if (event.target === overlay) this.closePreview(); });
    this.host.appendChild(overlay);
    this.previewOverlay = overlay;
    this.onPreviewKeyDown = (event) => {
      if (event.key === 'Escape') { event.stopImmediatePropagation(); this.closePreview(); }
    };
    window.addEventListener('keydown', this.onPreviewKeyDown, true);
    close.focus();
    if (!published) video.play().catch(() => {});
  }

  closePreview() {
    const video = this.previewOverlay?.querySelector('video');
    if (video) { video.pause(); video.removeAttribute('src'); video.load(); }
    const frame = this.previewOverlay?.querySelector('iframe');
    if (frame) frame.removeAttribute('src');
    this.previewOverlay?.remove();
    this.previewOverlay = null;
    if (this.onPreviewKeyDown) window.removeEventListener('keydown', this.onPreviewKeyDown, true);
    this.onPreviewKeyDown = null;
  }

  hide() { this.closePreview(); this.closeChapter(); this.root?.remove(); this.root = null; }
}
