import * as THREE from 'three';
import { fightCameraFrame, minimumDistanceForFighters } from './FightCamera.js';

/**
 * Juice
 * -----
 * The "feel" layer. Owns screen shake, slow-motion, hit-spark particles,
 * and a subtle camera dolly when the match gets close to KO. Nothing in
 * here changes gameplay state — it only modifies the camera and spawns
 * cosmetic geometry, so removing the Juice instance keeps the game
 * fully playable (just less satisfying).
 *
 * Combat code calls these high-level methods:
 *   juice.shake(amp, duration)
 *   juice.hitStop(duration)
 *   juice.slowMo(strength, duration)
 *   juice.cinematicFocus(worldPos, zoom, duration)
 *   juice.spawnHitSpark(worldPos, color)
 *
 * The main loop calls juice.update(realDt, lowHpRatio) once per frame
 * with the *unscaled* dt so shakes and slow-mo timers still tick during
 * slow-motion.
 *
 * getDtScale() returns the factor to multiply game dt by — 1.0 normally,
 * lower during slow-mo. main.js applies this to everything except the
 * juice update itself and audio.
 */
export class Juice {
  /**
   * @param {object} opts
   * @param {THREE.PerspectiveCamera} opts.camera
   * @param {THREE.Scene} opts.scene
   */
  constructor({ camera, scene }) {
    this.camera = camera;
    this.scene = scene;
    this._baseCameraPos = camera.position.clone();
    this._baseCameraLook = new THREE.Vector3(0, 1.2, 0);

    // Shake state.
    this._shakeAmp = 0;
    this._shakeTimer = 0;
    this._shakeDuration = 0.25;

    // Slow-mo state.
    this._slowMoStrength = 0; // 0..1, 1 = full freeze
    this._slowMoTimer = 0;

    // Hit-stop freezes gameplay for a few frames while effects and the
    // renderer continue. This makes contact readable without delaying input.
    this._hitStopTimer = 0;

    // Short impact focus used by supers and round-ending blows.
    this._focusTimer = 0;
    this._focusDuration = 0;
    this._focusZoom = 1;
    this._focusPoint = this._baseCameraLook.clone();

    // Camera dolly (zoom-in on low HP).
    this._zoomCurrent = 1.0;

    // Hit-spark particles.
    /** @type {Array<{mesh: THREE.Mesh, velocity: THREE.Vector3, lifespan: number, age: number}>} */
    this._particles = [];
    this._superEffects = [];
    this._sparkGroup = new THREE.Group();
    this._sparkGroup.name = 'juice_sparks';
    scene.add(this._sparkGroup);
  }

  /**
   * Trigger camera shake. Multiple calls take the max amplitude/duration.
   * @param {number} amp       Metres of jitter at peak (~0.05–0.3 is the useful range).
   * @param {number} duration  Seconds.
   */
  shake(amp, duration = 0.25) {
    this._shakeAmp = Math.max(this._shakeAmp, amp);
    if (duration > this._shakeTimer) {
      this._shakeTimer = duration;
      this._shakeDuration = duration;
    }
  }

  /**
   * Trigger slow-motion. The Juice produces a dt-multiplier that the main
   * loop applies to all gameplay. Audio + this update tick stay realtime.
   * @param {number} strength  0..1; 0.7 means "30% speed".
   * @param {number} duration  Seconds in real time.
   */
  slowMo(strength = 0.7, duration = 0.4) {
    this._slowMoStrength = Math.max(this._slowMoStrength, strength);
    this._slowMoTimer = Math.max(this._slowMoTimer, duration);
  }

  /** Freeze gameplay for a brief real-time duration while visuals keep updating. */
  hitStop(duration = 0.055) {
    this._hitStopTimer = Math.max(this._hitStopTimer, Math.max(0, duration));
  }

  /** Pull the camera toward an impact point, then ease back to the fight view. */
  cinematicFocus(worldPos, zoom = 0.76, duration = 0.42) {
    this._focusTimer = Math.max(this._focusTimer, duration);
    this._focusDuration = Math.max(this._focusDuration, duration);
    this._focusZoom = Math.min(this._focusZoom, Math.max(0.84, zoom));
    this._focusPoint.set(
      THREE.MathUtils.clamp(worldPos?.x ?? 0, -2.4, 2.4),
      THREE.MathUtils.clamp(worldPos?.y ?? 1.2, 0.8, 1.8),
      0,
    );
  }

  /**
   * Spawn a starburst of small bright spheres at a world position. They
   * spray outward, decelerate, fade, and clean themselves up.
   */
  spawnHitSpark(worldPos, color = 0xffd770, count = 10, speedScale = 1) {
    for (let i = 0; i < count; i++) {
      const geom = new THREE.SphereGeometry(0.04 + Math.random() * 0.03, 6, 6);
      const mat = new THREE.MeshBasicMaterial({
        color,
        transparent: true,
        opacity: 1,
        depthWrite: false,
      });
      const mesh = new THREE.Mesh(geom, mat);
      mesh.position.copy(worldPos);
      const angle = Math.random() * Math.PI * 2;
      const speed = (2 + Math.random() * 4) * speedScale;
      this._particles.push({
        mesh,
        velocity: new THREE.Vector3(
          Math.cos(angle) * speed,
          Math.sin(angle) * speed + 1.5,
          (Math.random() - 0.5) * 0.5,
        ),
        lifespan: 0.32 + Math.random() * 0.15,
        age: 0,
      });
      this._sparkGroup.add(mesh);
    }
  }

  /** Brief readable shapes for supers. These are cosmetic and never move a fighter. */
  spawnSuperEffect(worldPos, color = 0xffd770, style = 'impact', startup = false) {
    const addShape = (geometry, { angle = 0, offsetX = 0, offsetY = 0,
      duration = 0.32, scaleTo = 1.65, opacity = 0.85 } = {}) => {
      const material = new THREE.MeshBasicMaterial({
        color, transparent: true, opacity, depthWrite: false,
        blending: THREE.AdditiveBlending, side: THREE.DoubleSide,
      });
      const mesh = new THREE.Mesh(geometry, material);
      mesh.position.set(worldPos.x + offsetX, worldPos.y + offsetY, (worldPos.z ?? 0) + 0.12);
      mesh.rotation.z = angle;
      this._sparkGroup.add(mesh);
      this._superEffects.push({ mesh, age: 0, duration, scaleTo, opacity });
    };
    const ring = (radius, width, options = {}) =>
      addShape(new THREE.TorusGeometry(radius, width, 4, 40), options);
    const streak = (length, angle, offsetY = 0) =>
      addShape(new THREE.PlaneGeometry(length, 0.035, 1, 1), {
        angle, offsetY, duration: 0.24, scaleTo: 1.35, opacity: 0.8,
      });

    if (startup) {
      ring(0.39, 0.025, { duration: 0.31, scaleTo: 1.25, opacity: 0.62 });
      return;
    }
    // Keep the silhouette visible: the effect starts small, expands, and
    // fades within a fraction of a second rather than filling the screen.
    if (style === 'precision') {
      ring(0.25, 0.012, { duration: 0.33, scaleTo: 2.1 });
      ring(0.43, 0.009, { duration: 0.29, scaleTo: 1.35, opacity: 0.65 });
      streak(0.72, -0.58);
    } else if (style === 'shadow') {
      addShape(new THREE.TorusGeometry(0.43, 0.028, 4, 28, Math.PI * 1.45), {
        angle: -0.7, duration: 0.31, scaleTo: 1.8,
      });
      streak(0.95, -0.62, 0.12);
      streak(0.64, -0.62, -0.14);
    } else if (style === 'rush') {
      ring(0.34, 0.025, { duration: 0.29, scaleTo: 1.7 });
      streak(0.8, 0, 0.25);
      streak(1.05, 0, 0);
      streak(0.7, 0, -0.23);
    } else if (style === 'heavy') {
      ring(0.31, 0.047, { duration: 0.37, scaleTo: 2.1 });
      ring(0.47, 0.018, { duration: 0.35, scaleTo: 1.7, opacity: 0.58 });
      streak(0.82, 0.78);
      streak(0.82, -0.78);
    } else {
      ring(0.37, 0.028, { duration: 0.32, scaleTo: 1.75 });
      streak(0.78, 0.35);
    }
  }

  /** Dt multiplier the main loop should apply to gameplay updates. */
  getDtScale() {
    if (this._hitStopTimer > 0) return 0;
    if (this._slowMoTimer <= 0) return 1.0;
    return 1.0 - this._slowMoStrength;
  }

  /**
   * Per-frame update. Pass the REAL (unscaled) dt and the LOWER of the
   * two fighters' HP ratios so we can drive the low-HP dolly.
   */
  update(realDt, lowHpRatio = 1.0, fighters = []) {
    if (this._hitStopTimer > 0) {
      this._hitStopTimer = Math.max(0, this._hitStopTimer - realDt);
    }

    // Slow-mo countdown.
    if (this._slowMoTimer > 0) {
      this._slowMoTimer -= realDt;
      if (this._slowMoTimer <= 0) {
        this._slowMoTimer = 0;
        this._slowMoStrength = 0;
      }
    }

    // Fit both fighters before applying cinematic effects. This also lets the
    // view follow them into the outer half of the stage instead of losing one.
    const frame = fightCameraFrame(fighters, this.camera.aspect, this.camera.fov);
    const follow = Math.min(1, realDt * 11);
    this._baseCameraLook.x += (frame.x - this._baseCameraLook.x) * follow;
    this._baseCameraLook.y += (frame.y - this._baseCameraLook.y) * follow;
    this._baseCameraPos.z += (frame.distance - this._baseCameraPos.z) * follow;

    // Low-HP and impact zooms remain cosmetic: visibility wins over zoom.
    const targetZoom = lowHpRatio < 0.25 ? 0.94 : 1.0;
    this._zoomCurrent += (targetZoom - this._zoomCurrent) * Math.min(1, realDt * 3);

    // Shake countdown.
    let shakeFactor = 0;
    if (this._shakeTimer > 0) {
      this._shakeTimer -= realDt;
      const t = Math.max(0, this._shakeTimer / this._shakeDuration);
      shakeFactor = this._shakeAmp * t;
      if (this._shakeTimer <= 0) {
        this._shakeTimer = 0;
        this._shakeAmp = 0;
      }
    }

    const dx = THREE.MathUtils.clamp((Math.random() - 0.5) * 2 * shakeFactor, -0.08, 0.08);
    const dy = THREE.MathUtils.clamp((Math.random() - 0.5) * 2 * shakeFactor, -0.05, 0.05);

    let focusBlend = 0;
    if (this._focusTimer > 0) {
      this._focusTimer = Math.max(0, this._focusTimer - realDt);
      const remaining = this._focusDuration > 0 ? this._focusTimer / this._focusDuration : 0;
      focusBlend = Math.sin(Math.PI * Math.max(0, Math.min(1, remaining)));
      if (this._focusTimer <= 0) {
        this._focusDuration = 0;
        this._focusZoom = 1;
      }
    }

    const cameraZoom = this._zoomCurrent * THREE.MathUtils.lerp(1, this._focusZoom, focusBlend);
    const cameraLook = this._baseCameraLook.clone().lerp(this._focusPoint, focusBlend * 0.12);
    const safeDistance = minimumDistanceForFighters(
      fighters, cameraLook.x, this.camera.aspect, this.camera.fov, 1.2, cameraLook.y,
    );

    this.camera.position.set(
      cameraLook.x + dx,
      cameraLook.y + 0.4 + dy,
      Math.max(this._baseCameraPos.z * cameraZoom, safeDistance),
    );
    this.camera.lookAt(cameraLook);

    // Sparks: integrate, decay, dispose.
    for (let i = this._particles.length - 1; i >= 0; i--) {
      const p = this._particles[i];
      p.age += realDt;
      if (p.age >= p.lifespan) {
        this._sparkGroup.remove(p.mesh);
        p.mesh.geometry.dispose();
        p.mesh.material.dispose();
        this._particles.splice(i, 1);
        continue;
      }
      p.mesh.position.x += p.velocity.x * realDt;
      p.mesh.position.y += p.velocity.y * realDt;
      p.mesh.position.z += p.velocity.z * realDt;
      // Gravity.
      p.velocity.y -= 8 * realDt;
      // Fade + shrink.
      const lifeT = p.age / p.lifespan;
      p.mesh.material.opacity = 1 - lifeT;
      p.mesh.scale.setScalar(1 - lifeT * 0.6);
    }
    for (let i = this._superEffects.length - 1; i >= 0; i--) {
      const effect = this._superEffects[i];
      effect.age += realDt;
      if (effect.age >= effect.duration) {
        this._sparkGroup.remove(effect.mesh);
        effect.mesh.geometry.dispose();
        effect.mesh.material.dispose();
        this._superEffects.splice(i, 1);
        continue;
      }
      const progress = effect.age / effect.duration;
      effect.mesh.scale.setScalar(0.72 + (effect.scaleTo - 0.72) * progress);
      effect.mesh.material.opacity = effect.opacity * (1 - progress) ** 1.6;
    }
  }
}
