/**
 * KnockdownState
 * --------------
 * Floored. Plays knockdown clip, then get_up, then returns to idle. The
 * fighter cannot be hit again while down (invulnerable wake-up frames are
 * configured here in Phase 4).
 */
export const KnockdownState = {
  name: 'knockdown',

  enter(fighter, _prev, payload = {}) {
    this._phase = 'down';
    this._timer = 0.8;
    this._elapsed = 0;
    this._throwVisualOffset = payload.visualOffset ?? 0;
    fighter.position.y = 0;
    fighter.velocity.y = 0;
    // A sweep should drop the defender near the contact point. Keeping the
    // full hit impulse throughout the down/get-up animation sends them across
    // the arena and forces the camera to zoom far out.
    fighter.velocity.x = Math.sign(fighter.velocity.x) * Math.min(Math.abs(fighter.velocity.x), 0.8);
    fighter.isGrounded = true;
    fighter.visualOffsetY = this._throwVisualOffset;
    fighter.forceVisualGrounding = true;
    if (!payload.continueFall) fighter.playClip('knockdown', { loop: false });
  },

  update(dt, input, fighter) {
    this._elapsed += dt;
    fighter.position.y = 0;
    fighter.velocity.y = 0;
    fighter.isGrounded = true;
    fighter.velocity.x *= Math.max(0, 1 - dt * 12);
    this._timer -= dt;
    if (this._phase === 'down') {
      // The animated mesh decides the fall pose; Fighter keeps its lowest
      // visible point on the stage floor throughout the down phase.
      const quickRise = this._elapsed >= 0.28 && (
        input.consumeBuffered?.('up', fighter.playerId, 190) ||
        input.wasPressed?.('up', fighter.playerId)
      );
      if (quickRise) {
        this._phase = 'getup';
        this._timer = 0.3;
        fighter.visualOffsetY = 0;
        fighter.forceVisualGrounding = false;
        fighter.invulnerabilityTimer = Math.max(fighter.invulnerabilityTimer, 0.18);
        fighter.playClip('get_up', { loop: false, timeScale: 1.8, fade: 0.04 });
      }
    }
    if (this._phase === 'down' && this._timer <= 0) {
      this._phase = 'getup';
      this._timer = 0.6;
      fighter.visualOffsetY = 0;
      fighter.forceVisualGrounding = false;
      fighter.playClip('get_up', { loop: false });
    } else if (this._phase === 'getup' && this._timer <= 0) {
      return 'idle';
    }
    return null;
  },

  exit(fighter) {
    fighter.visualOffsetY = 0;
    fighter.forceVisualGrounding = false;
    fighter.position.y = 0;
    fighter.velocity.y = 0;
    fighter.isGrounded = true;
  },
};
