const STORAGE_KEY = 'dsf.economy.v1';

const DEFAULTS = Object.freeze({
  coins: 0,
  gems: 0,
  xp: 0,
});

function readStored(storage) {
  try {
    const raw = storage?.getItem(STORAGE_KEY);
    if (!raw) return {};
    const parsed = JSON.parse(raw);
    return parsed && typeof parsed === 'object' ? parsed : {};
  } catch {
    return {};
  }
}

function writeStored(storage, value) {
  try {
    storage?.setItem(STORAGE_KEY, JSON.stringify(value));
  } catch {
    /* Storage can fail in private mode; economy should not crash the game. */
  }
}

export class Economy {
  constructor({ storage = globalThis.localStorage } = {}) {
    this.storage = storage;
    this._values = { ...DEFAULTS, ...readStored(storage) };
    this._listeners = new Set();
  }

  get coins() {
    return this._values.coins ?? 0;
  }

  get xp() {
    return this._values.xp ?? 0;
  }

  get gems() {
    return this._values.gems ?? 0;
  }

  get level() {
    return Math.floor(this.xp / 500) + 1;
  }

  addCoins(amount) {
    const safeAmount = Math.max(0, Number(amount) || 0);
    if (safeAmount <= 0) return this.coins;
    this._values.coins = this.coins + safeAmount;
    writeStored(this.storage, this._values);
    this._notify();
    return this.coins;
  }

  addXP(amount) {
    const safeAmount = Math.max(0, Number(amount) || 0);
    if (safeAmount <= 0) return this.xp;
    this._values.xp = this.xp + safeAmount;
    writeStored(this.storage, this._values);
    this._notify();
    return this.xp;
  }

  addGems(amount) {
    const safeAmount = Math.max(0, Number(amount) || 0);
    if (safeAmount <= 0) return this.gems;
    this._values.gems = this.gems + safeAmount;
    writeStored(this.storage, this._values);
    this._notify();
    return this.gems;
  }

  subscribe(listener) {
    this._listeners.add(listener);
    return () => this._listeners.delete(listener);
  }

  snapshot() {
    return Object.freeze({ ...this._values });
  }

  _notify() {
    for (const cb of this._listeners) {
      try { cb(this); } catch { /* Listener errors should not break gameplay. */ }
    }
  }
}
