const STORAGE_KEY = 'dsf.daily.v1';

export const LOGIN_REWARDS = [
  { coins: 50, xp: 30, gems: 0 },
  { coins: 75, xp: 40, gems: 0 },
  { coins: 100, xp: 50, gems: 1 },
  { coins: 125, xp: 60, gems: 0 },
  { coins: 150, xp: 75, gems: 0 },
  { coins: 200, xp: 90, gems: 0 },
  { coins: 300, xp: 150, gems: 3 },
];

export const DAILY_MISSION_DEFINITIONS = [
  { id: 'win_matches', title: 'Street Champion', detail: 'Win 2 matches', event: 'match_win', target: 2, reward: { coins: 90, xp: 60 } },
  { id: 'combo_five', title: 'Combo Ustad', detail: 'Land a 5-hit combo', event: 'combo', target: 5, mode: 'max', reward: { coins: 75, xp: 55 } },
  { id: 'training_clear', title: 'Daily Practice', detail: 'Complete a combo trial', event: 'training_clear', target: 1, reward: { coins: 55, xp: 45 } },
  { id: 'throw_escape', title: 'No Free Daav', detail: 'Escape 2 throws', event: 'throw_escape', target: 2, reward: { coins: 80, xp: 55 } },
  { id: 'super_finish', title: 'Cinematic Finish', detail: 'Win a round with a Super', event: 'super_finish', target: 1, reward: { coins: 110, xp: 75 } },
  { id: 'tough_win', title: 'Serious Rival', detail: 'Defeat Medium or Hard CPU', event: 'tough_win', target: 1, reward: { coins: 120, xp: 85 } },
  { id: 'land_hits', title: 'Keep Swinging', detail: 'Land 20 hits', event: 'land_hits', target: 20, reward: { coins: 70, xp: 50 } },
];

export function localDateKey(date = new Date()) {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

function dateOrdinal(key) {
  const [year, month, day] = key.split('-').map(Number);
  return Math.floor(Date.UTC(year, month - 1, day) / 86400000);
}

function hashDate(key) {
  let hash = 2166136261;
  for (const char of key) hash = Math.imul(hash ^ char.charCodeAt(0), 16777619);
  return hash >>> 0;
}

function missionsForDate(key) {
  const pool = [...DAILY_MISSION_DEFINITIONS];
  let seed = hashDate(key);
  const result = [];
  while (result.length < 3) {
    seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
    result.push(pool.splice(seed % pool.length, 1)[0]);
  }
  return result.map((mission) => ({ id: mission.id, progress: 0, claimed: false }));
}

function rewardText(reward) {
  return `${reward.coins} coins · ${reward.xp} XP${reward.gems ? ` · ${reward.gems} gem${reward.gems > 1 ? 's' : ''}` : ''}`;
}

export class DailyEngagement {
  constructor({ storage = globalThis.localStorage, economy, now = () => new Date() } = {}) {
    this.storage = storage;
    this.economy = economy;
    this.now = now;
    this.listeners = new Set();
    this.data = {
      date: null,
      missions: [],
      rerollDate: null,
      login: { lastClaimDate: null, streak: 0 },
    };
    try {
      const stored = JSON.parse(storage?.getItem(STORAGE_KEY) || '{}');
      this.data = {
        ...this.data,
        ...stored,
        login: { ...this.data.login, ...(stored.login ?? {}) },
      };
    } catch { /* Start with clean daily data. */ }
    this._ensureDay();
  }

  snapshot() {
    this._ensureDay();
    return {
      date: this.data.date,
      missions: this.data.missions.map((entry) => ({ ...this._definition(entry.id), ...entry })),
      rerollUsed: this.data.rerollDate === this.data.date,
      login: { ...this.data.login },
      loginReady: this.data.login.lastClaimDate !== this.data.date,
      loginDay: this._nextLoginDay(),
    };
  }

  summary() {
    const state = this.snapshot();
    return {
      loginReady: state.loginReady,
      claimable: state.missions.filter((mission) => mission.progress >= mission.target && !mission.claimed).length,
      completed: state.missions.filter((mission) => mission.claimed).length,
    };
  }

  record(event, payload = {}) {
    this._ensureDay();
    const newlyCompleted = [];
    for (const entry of this.data.missions) {
      const definition = this._definition(entry.id);
      if (!definition || definition.event !== event || entry.claimed) continue;
      const before = entry.progress;
      const value = Math.max(0, Number(payload.value ?? 1) || 0);
      entry.progress = Math.min(
        definition.target,
        definition.mode === 'max' ? Math.max(entry.progress, value) : entry.progress + value,
      );
      if (before < definition.target && entry.progress >= definition.target) newlyCompleted.push(definition);
    }
    if (newlyCompleted.length) {
      this._save();
      this._notify();
    } else if (this.data.missions.some((entry) => this._definition(entry.id)?.event === event)) {
      this._save();
    }
    return newlyCompleted;
  }

  claimMission(id) {
    this._ensureDay();
    const entry = this.data.missions.find((mission) => mission.id === id);
    const definition = this._definition(id);
    if (!entry || !definition || entry.claimed || entry.progress < definition.target) return null;
    entry.claimed = true;
    this._grant(definition.reward);
    this._save();
    this._notify();
    return { ...definition.reward };
  }

  claimLogin() {
    this._ensureDay();
    const today = this.data.date;
    if (this.data.login.lastClaimDate === today) return null;
    const previous = this.data.login.lastClaimDate;
    const consecutive = previous && dateOrdinal(today) - dateOrdinal(previous) === 1;
    this.data.login.streak = consecutive
      ? (this.data.login.streak % LOGIN_REWARDS.length) + 1
      : 1;
    this.data.login.lastClaimDate = today;
    const reward = LOGIN_REWARDS[this.data.login.streak - 1];
    this._grant(reward);
    this._save();
    this._notify();
    return { ...reward, day: this.data.login.streak };
  }

  rerollMission(id) {
    this._ensureDay();
    if (this.data.rerollDate === this.data.date) return null;
    const index = this.data.missions.findIndex((mission) => mission.id === id && !mission.claimed);
    if (index < 0) return null;
    const used = new Set(this.data.missions.map((mission) => mission.id));
    const available = DAILY_MISSION_DEFINITIONS.filter((mission) => !used.has(mission.id));
    if (!available.length) return null;
    const seed = hashDate(`${this.data.date}:${id}:reroll`);
    const replacement = available[seed % available.length];
    this.data.missions[index] = { id: replacement.id, progress: 0, claimed: false };
    this.data.rerollDate = this.data.date;
    this._save();
    this._notify();
    return { ...replacement };
  }

  subscribe(listener) {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  _nextLoginDay() {
    if (this.data.login.lastClaimDate === this.data.date) return this.data.login.streak || 1;
    const previous = this.data.login.lastClaimDate;
    const consecutive = previous && dateOrdinal(this.data.date) - dateOrdinal(previous) === 1;
    return consecutive ? (this.data.login.streak % LOGIN_REWARDS.length) + 1 : 1;
  }

  _ensureDay() {
    const today = localDateKey(this.now());
    if (this.data.date === today && this.data.missions.length === 3) return;
    this.data.date = today;
    this.data.missions = missionsForDate(today);
    this._save();
  }

  _definition(id) {
    return DAILY_MISSION_DEFINITIONS.find((mission) => mission.id === id);
  }

  _grant(reward) {
    this.economy?.addCoins(reward.coins ?? 0);
    this.economy?.addXP(reward.xp ?? 0);
    this.economy?.addGems(reward.gems ?? 0);
  }

  _save() {
    try { this.storage?.setItem(STORAGE_KEY, JSON.stringify(this.data)); } catch { /* Best effort. */ }
  }

  _notify() {
    for (const listener of this.listeners) {
      try { listener(this.snapshot()); } catch { /* UI listeners cannot break progress. */ }
    }
  }
}

export function showDailyRewards({ host, daily, economy, onBack }) {
  const wrap = document.createElement('div');
  wrap.dataset.dsfDaily = 'screen';
  wrap.style.cssText = `position:absolute;inset:0;z-index:75;display:flex;align-items:center;justify-content:center;box-sizing:border-box;padding:clamp(8px,2vh,20px);background:rgba(12,7,4,.94);color:#f5e9c9;font-family:'Segoe UI',system-ui,sans-serif;pointer-events:auto;overflow:hidden;`;

  const render = () => {
    const previousScroll = wrap.querySelector('[data-daily-scroll]')?.scrollTop ?? 0;
    const state = daily.snapshot();
    const days = LOGIN_REWARDS.map((reward, index) => {
      const day = index + 1;
      const active = day === state.loginDay;
      const claimed = state.login.lastClaimDate === state.date && day === state.login.streak;
      return `<div style="padding:10px 6px;border:2px solid ${active ? '#ffd770' : '#6b4d22'};border-radius:7px;background:${claimed ? '#24451f' : 'rgba(42,18,10,.9)'};text-align:center;"><b style="color:#ffd770;">DAY ${day}</b><span style="display:block;margin-top:4px;font-size:11px;">${rewardText(reward)}</span>${claimed ? '<span style="color:#86efac;font-weight:900;">CLAIMED</span>' : ''}</div>`;
    }).join('');
    const missions = state.missions.map((mission) => {
      const ready = mission.progress >= mission.target && !mission.claimed;
      return `<article style="padding:13px;border:2px solid ${mission.claimed ? '#4ade80' : ready ? '#ffd770' : '#7c5b27'};border-radius:8px;background:rgba(42,18,10,.92);"><b style="color:#fff3b0;">${mission.title}</b><span style="display:block;margin-top:3px;font-size:12px;opacity:.82;">${mission.detail}</span><div style="height:8px;margin:9px 0 6px;border-radius:6px;background:#24130a;overflow:hidden;"><div style="height:100%;width:${Math.min(100, mission.progress / mission.target * 100)}%;background:#f5b642;"></div></div><span style="font-size:12px;">${mission.progress}/${mission.target} · ${rewardText(mission.reward)}</span><div style="display:flex;gap:6px;margin-top:8px;"><button data-claim="${mission.id}" ${ready ? '' : 'disabled'}>${mission.claimed ? 'CLAIMED' : 'CLAIM'}</button><button data-reroll="${mission.id}" ${state.rerollUsed || mission.claimed ? 'disabled' : ''}>REROLL</button></div></article>`;
    }).join('');
    wrap.innerHTML = `<section style="box-sizing:border-box;width:min(940px,100%);max-height:calc(100vh - 16px);max-height:calc(100dvh - 16px);min-height:0;padding:clamp(10px,2vw,22px);border:2px solid #c79b3a;border-radius:10px;background:rgba(20,12,6,.98);display:flex;flex-direction:column;overflow:hidden;"><header style="display:flex;align-items:center;justify-content:space-between;gap:12px;flex:0 0 auto;"><h2 style="margin:0;color:#ffd770;letter-spacing:.1em;">DAILY REWARDS</h2><button data-back style="flex:0 0 auto;min-height:44px;">BACK</button></header><div data-daily-scroll style="flex:1 1 auto;min-height:0;overflow-y:auto;overscroll-behavior:contain;touch-action:pan-y;-webkit-overflow-scrolling:touch;padding:2px 4px 2px 0;"><p style="margin:8px 0 14px;">${state.date} · Login streak ${state.login.streak}/7 · Wallet ${economy.coins} coins / ${economy.gems} gems</p><div style="display:grid;grid-template-columns:repeat(7,minmax(82px,1fr));gap:6px;overflow-x:auto;">${days}</div><button data-login ${state.loginReady ? '' : 'disabled'} style="margin:12px 0;padding:9px 15px;">${state.loginReady ? `CLAIM DAY ${state.loginDay}` : 'LOGIN REWARD CLAIMED'}</button><h3 style="color:#ffd770;">TODAY'S MISSIONS</h3><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:9px;">${missions}</div><p style="font-size:12px;opacity:.7;">One mission may be rerolled each day. New missions use your device's local calendar date.</p></div></section>`;
    for (const button of wrap.querySelectorAll('button')) {
      button.style.cssText += 'border:1px solid #ffd770;border-radius:5px;background:#542313;color:#fff3b0;font-weight:900;cursor:pointer;padding:7px 10px;';
    }
    wrap.querySelector('[data-login]')?.addEventListener('click', () => { daily.claimLogin(); render(); });
    wrap.querySelector('[data-back]')?.addEventListener('click', () => { wrap.remove(); onBack?.(); });
    for (const button of wrap.querySelectorAll('[data-claim]')) button.addEventListener('click', () => { daily.claimMission(button.dataset.claim); render(); });
    for (const button of wrap.querySelectorAll('[data-reroll]')) button.addEventListener('click', () => { daily.rerollMission(button.dataset.reroll); render(); });
    wrap.querySelector('[data-daily-scroll]').scrollTop = previousScroll;
  };
  host.appendChild(wrap);
  render();
  return wrap;
}
