/** Short, skippable pre-match card. The longer fighter reveal remains once-only. */
export class VersusIntro {
  constructor(host) {
    this.host = host;
    this.root = null;
    this.finish = null;
  }

  show({ p1, p2, stage }) {
    this.hide(false);
    return new Promise((resolve) => {
      const root = document.createElement('section');
      root.className = 'dsf-versus-intro';
      root.setAttribute('role', 'dialog');
      root.setAttribute('aria-modal', 'true');
      root.setAttribute('aria-label', `${p1.name} versus ${p2.name}`);
      root.style.cssText = 'position:fixed;inset:0;z-index:90;display:flex;align-items:center;justify-content:center;padding:16px;background:radial-gradient(circle at center,#502413,#140906 72%);color:#ffe5aa;font-family:Segoe UI,system-ui,sans-serif;pointer-events:auto';
      const panel = document.createElement('div');
      panel.style.cssText = 'width:min(960px,100%);text-align:center';
      const eyebrow = document.createElement('div');
      eyebrow.textContent = 'NEXT FIGHT';
      eyebrow.style.cssText = 'letter-spacing:.24em;color:#d9a73a;font-weight:800';
      const matchup = document.createElement('div');
      matchup.style.cssText = 'display:grid;grid-template-columns:minmax(0,1fr) auto minmax(0,1fr);align-items:center;gap:clamp(6px,2vw,24px);margin:20px 0';
      for (const [index, fighter] of [p1, p2].entries()) {
        if (index === 1) {
          const vs = document.createElement('strong');
          vs.textContent = 'VS';
          vs.style.cssText = 'font-size:clamp(30px,7vw,74px);color:#ffc444;text-shadow:0 3px 16px #d64516';
          matchup.appendChild(vs);
        }
        const card = document.createElement('div');
        card.style.cssText = 'min-width:0;background:#25110c;border:2px solid #bd8b2b;border-radius:12px;padding:10px';
        const image = document.createElement('img');
        image.src = fighter.portrait;
        image.alt = '';
        image.style.cssText = 'display:block;width:100%;height:clamp(100px,27vh,260px);object-fit:contain';
        const name = document.createElement('div');
        name.textContent = fighter.name;
        name.style.cssText = 'font-size:clamp(15px,2.5vw,26px);font-weight:800;overflow-wrap:anywhere';
        card.append(image, name);
        matchup.appendChild(card);
      }
      const location = document.createElement('div');
      location.textContent = stage.name;
      location.style.cssText = 'font-size:clamp(17px,3vw,28px);font-weight:700;margin-bottom:18px';
      const skip = document.createElement('button');
      skip.type = 'button'; skip.textContent = 'Fight now →';
      skip.style.cssText = 'background:#783416;color:#ffe6ae;border:2px solid #d4a743;border-radius:8px;padding:11px 24px;font:700 17px Segoe UI,system-ui;cursor:pointer';
      panel.append(eyebrow, matchup, location, skip);
      root.appendChild(panel);
      this.host.appendChild(root);
      this.root = root;
      const onKey = (event) => {
        if (['Enter', 'Escape', ' '].includes(event.key)) {
          event.preventDefault(); event.stopImmediatePropagation(); this.hide(true);
        }
      };
      const timer = setTimeout(() => this.hide(true), 2200);
      this.finish = (continueFight = false) => {
        clearTimeout(timer);
        window.removeEventListener('keydown', onKey, true);
        root.remove();
        this.root = null;
        this.finish = null;
        resolve(continueFight);
      };
      window.addEventListener('keydown', onKey, true);
      skip.addEventListener('click', () => this.hide(true));
      skip.focus();
    });
  }

  hide(continueFight = false) { this.finish?.(continueFight); }
}
