export class TrainingProgress {
  constructor({ storage = globalThis.localStorage } = {}) {
    this.storage = storage;
    this.data = { completed: [], masteryXp: {} };
    try {
      const saved = JSON.parse(storage?.getItem(STORAGE_KEY) || '{}');
      this.data.completed = Array.isArray(saved.completed) ? saved.completed : [];
      this.data.masteryXp = saved.masteryXp && typeof saved.masteryXp === 'object' ? saved.masteryXp : {};
    } catch { /* Start with clean local progress. */ }
  }

  isComplete(trialId) {
    return this.data.completed.includes(trialId);
  }

  complete(trial) {
    if (this.isComplete(trial.id)) return { firstClear: false, reward: { coins: 0, xp: 0, gems: 0 } };
    this.data.completed.push(trial.id);
    this.data.masteryXp.rickshaw_rider_bilal =
      (this.data.masteryXp.rickshaw_rider_bilal ?? 0) + trial.reward.xp;
    try { this.storage?.setItem(STORAGE_KEY, JSON.stringify(this.data)); } catch { /* Best effort. */ }
    return { firstClear: true, reward: { ...trial.reward } };
  }

  mastery(characterId) {
    return this.data.masteryXp[characterId] ?? 0;
  }

  completedCount() {
    return BILAL_TRIALS.filter((trial) => this.isComplete(trial.id)).length;
  }
}

export class TrainingTrialTracker {
  constructor(trial, onComplete = null) {
    this.trial = trial;
    this.onComplete = onComplete;
    this.reset();
  }

  reset() {
    this.index = 0;
    this.complete = false;
    this.stepTimer = 0;
  }

  update(dt) {
    if (this.complete || this.index === 0) return;
    this.stepTimer -= dt;
    if (this.stepTimer <= 0) this.reset();
  }

  record(eventId) {
    if (this.complete) return false;
    const expected = this.trial.steps[this.index];
    if (eventId === expected) {
      this.index += 1;
      this.stepTimer = 2.2;
      if (this.index >= this.trial.steps.length) {
        this.complete = true;
        this.onComplete?.(this.trial);
      }
      return true;
    }
    this.index = eventId === this.trial.steps[0] ? 1 : 0;
    this.stepTimer = this.index ? 2.2 : 0;
    return false;
  }
}

const ACTION_LABELS = {
  left: '←', right: '→', up: '↑', down: '↓', punch_light: 'LP', punch_medium: 'MP',
  punch_heavy: 'HP', kick_light: 'LK', kick_medium: 'MK', kick_heavy: 'HK',
  special: 'SPECIAL', super: 'SUPER', throw: 'THR', block: 'BLK', hadoken: 'HADO', shoryuken: 'DP',
};

export class TrainingSession {
  constructor({ host, trial, player, dummy, input, performance, economy, progress, onExit, onEngagementEvent = null }) {
    this.host = host;
    this.trial = trial;
    this.player = player;
    this.dummy = dummy;
    this.input = input;
    this.performance = performance;
    this.economy = economy;
    this.progress = progress;
    this.onExit = onExit;
    this.onEngagementEvent = onEngagementEvent;
    this.dummyInput = new SyntheticInput();
    this.dummyMode = 'stationary';
    this.infiniteHealth = true;
    this.infiniteMeter = true;
    this.inputHistory = [];
    this._lastPlayerState = player.stateMachine.currentName;
    this._dummyHealTimer = 0;
    this._renderAccumulator = 0;
    this._guideActive = false;
    this._guideIndex = 0;
    this._guideTimer = 0;
    this.tracker = new TrainingTrialTracker(trial, () => this._completeTrial());
    this._buildPanel();
    this.resetPositions();
  }

  update(dt) {
    this.tracker.update(dt);
    if (this._guideActive) {
      this._guideTimer -= dt;
      if (this._guideTimer <= 0) {
        this._guideIndex += 1;
        this._guideTimer = 0.7;
        if (this._guideIndex >= this.trial.steps.length) {
          this._guideActive = false;
          this._guideIndex = 0;
        }
      }
    }
    this._captureInputs();
    const state = this.player.stateMachine.currentName;
    if (state === 'dash' && this._lastPlayerState !== 'dash' && this.player.velocity.x * this.player.facing > 0) {
      this.tracker.record('dash_forward');
    }
    this._lastPlayerState = state;

    if (this.infiniteMeter) this.player.superMeter = this.player.maxSuperMeter;
    if (this.infiniteHealth && this.player.hp < this.player.maxHp) {
      this.player.hp = this.player.maxHp;
      if (this.player.stateMachine.currentName === 'ko') this.player.stateMachine.change('idle');
    }
    this._dummyHealTimer -= dt;
    if (this.infiniteHealth && this._dummyHealTimer <= 0 && this.dummy.hp < this.dummy.maxHp) {
      this.dummy.hp = this.dummy.maxHp;
    }
    if (this.dummy.hp <= 0) {
      this.dummy.hp = this.dummy.maxHp;
      this.dummy.stateMachine.change('idle');
    }

    this._updateDummyInput();
    this._renderAccumulator += dt;
    if (this._renderAccumulator >= 0.08) {
      this._renderAccumulator = 0;
      this._render();
    }
  }

  recordHit(move, { blocked = false } = {}) {
    if (!blocked) this.tracker.record(move.id);
    this._dummyHealTimer = 0.7;
    if (this.dummy.hp <= 0) {
      this.dummy.hp = this.dummy.maxHp;
      this.dummy.stateMachine.change('idle');
    }
    this._render();
  }

  resetPositions() {
    const fighters = [this.player, this.dummy];
    for (let i = 0; i < fighters.length; i++) {
      const fighter = fighters[i];
      fighter.position.x = i === 0 ? -0.42 : 0.42;
      fighter.position.y = 0;
      fighter.velocity.x = 0;
      fighter.velocity.y = 0;
      fighter.facing = i === 0 ? 1 : -1;
      fighter.isGrounded = true;
      fighter.hp = fighter.maxHp;
      fighter.invulnerabilityTimer = 0;
      fighter.stateMachine.change('idle');
    }
    this.tracker.reset();
    this.performance?.endChains();
    this.player._projectiles?.clear?.();
    this._render();
  }

  _captureInputs() {
    for (const action of Object.keys(ACTION_LABELS)) {
      if (!this.input.wasPressed(action, this.player.playerId)) continue;
      this.inputHistory.push(ACTION_LABELS[action]);
      if (this.inputHistory.length > 10) this.inputHistory.shift();
    }
  }

  _updateDummyInput() {
    const held = new Set();
    const pressed = new Set();
    if (this.dummyMode === 'block') {
      held.add('block');
    } else if (this.dummyMode === 'counter') {
      const attack = this.player._currentAttack;
      const activeEnd = (attack?.move?.startup ?? 0) + (attack?.move?.active ?? 0);
      if (attack && attack.frame < activeEnd) held.add('block');
      else if (attack && attack.frame >= activeEnd && this.dummy.stateMachine.currentName === 'idle') {
        pressed.add('punch_medium');
      }
    }
    this.dummyInput.set(held, pressed);
  }

  _completeTrial() {
    const result = this.progress.complete(this.trial);
    this.onEngagementEvent?.('training_clear', { value: 1, trialId: this.trial.id });
    if (result.firstClear) {
      this.economy.addCoins(result.reward.coins);
      this.economy.addXP(result.reward.xp);
      this.economy.addGems(result.reward.gems);
    }
    this._completionText = result.firstClear
      ? `FIRST CLEAR! +${result.reward.coins} coins · +${result.reward.xp} XP${result.reward.gems ? ` · +${result.reward.gems} gem` : ''}`
      : 'TRIAL COMPLETE · First-clear reward already claimed';
    this._render();
  }

  _buildPanel() {
    const panel = document.createElement('section');
    panel.dataset.dsfTraining = 'panel';
    panel.style.cssText = `position:absolute;left:14px;top:112px;z-index:22;width:min(360px,calc(100vw - 28px));padding:14px;border:2px solid #c79b3a;border-radius:10px;background:rgba(15,9,5,.9);color:#f5e9c9;font:13px/1.4 'Segoe UI',system-ui,sans-serif;pointer-events:auto;box-shadow:0 8px 28px rgba(0,0,0,.5);`;
    panel.innerHTML = `<div data-title></div><div data-steps></div><div data-stats></div><div data-inputs></div><div data-result></div><div data-actions style="display:flex;gap:6px;flex-wrap:wrap;margin-top:10px;"></div>`;
    this.host.appendChild(panel);
    this.panel = panel;
    const actions = panel.querySelector('[data-actions]');
    const button = (label, handler) => {
      const el = document.createElement('button');
      el.type = 'button';
      el.textContent = label;
      el.style.cssText = 'padding:7px 9px;border:1px solid #ffd770;border-radius:5px;background:#542313;color:#fff3b0;font-weight:800;cursor:pointer;';
      el.addEventListener('click', handler);
      actions.appendChild(el);
      return el;
    };
    button('RESET', () => this.resetPositions());
    button('PLAY GUIDE', () => {
      this._guideActive = true;
      this._guideIndex = 0;
      this._guideTimer = 0.7;
      this._render();
    });
    this._dummyButton = button('DUMMY: STATIONARY', () => {
      const modes = ['stationary', 'block', 'counter'];
      this.dummyMode = modes[(modes.indexOf(this.dummyMode) + 1) % modes.length];
      this._dummyButton.textContent = `DUMMY: ${this.dummyMode.toUpperCase()}`;
    });
    this._healthButton = button('HEALTH: ∞', () => {
      this.infiniteHealth = !this.infiniteHealth;
      this._healthButton.textContent = `HEALTH: ${this.infiniteHealth ? '∞' : 'NORMAL'}`;
    });
    this._meterButton = button('METER: ∞', () => {
      this.infiniteMeter = !this.infiniteMeter;
      this._meterButton.textContent = `METER: ${this.infiniteMeter ? '∞' : 'NORMAL'}`;
    });
    button('EXIT', () => this.onExit?.());
    this._render();
  }

  _render() {
    if (!this.panel) return;
    this.panel.querySelector('[data-title]').innerHTML = `<b style="color:#ffd770;font-size:15px;letter-spacing:.08em;">${this.trial.name}</b> <span style="opacity:.7;">· ${this.trial.difficulty}</span>`;
    this.panel.querySelector('[data-steps]').innerHTML = this.trial.labels.map((label, index) => {
      const done = index < this.tracker.index;
      const active = this._guideActive
        ? index === this._guideIndex
        : index === this.tracker.index && !this.tracker.complete;
      return `<div style="margin:4px 0;color:${done ? '#86efac' : active ? '#fff3b0' : '#9ca3af'};font-weight:${active ? 800 : 600};">${done ? '✓' : active ? '▶' : '○'} ${label}</div>`;
    }).join('');
    const combo = this.performance?.chain(0) ?? { hits: 0, damage: 0 };
    const timing = this.tracker.index > 0 && !this.tracker.complete
      ? `${this.tracker.stepTimer.toFixed(1)}s cancel window`
      : 'ready';
    this.panel.querySelector('[data-stats]').textContent = `Combo ${combo.hits} hits · ${combo.damage} damage · ${timing} · Bilal mastery ${this.progress.mastery('rickshaw_rider_bilal')} XP`;
    this.panel.querySelector('[data-inputs]').textContent = `Inputs: ${this.inputHistory.join('  ') || '—'}`;
    const result = this.panel.querySelector('[data-result]');
    result.textContent = this._completionText ?? '';
    result.style.cssText = 'margin-top:7px;color:#86efac;font-weight:900;';
  }

  dispose() {
    this.panel?.remove();
    this.panel = null;
  }
}

export function showTrainingSelect({ host, progress, economy, onStart, onBack }) {
  const wrap = document.createElement('div');
  wrap.dataset.dsfTraining = 'select';
  wrap.style.cssText = `position:absolute;inset:0;z-index:70;display:grid;place-items:center;padding:22px;background:rgba(12,7,4,.92);color:#f5e9c9;font-family:'Segoe UI',system-ui,sans-serif;pointer-events:auto;overflow:auto;`;
  const cards = BILAL_TRIALS.map((trial, index) => {
    const done = progress.isComplete(trial.id);
    const reward = `${trial.reward.coins} coins · ${trial.reward.xp} XP${trial.reward.gems ? ` · ${trial.reward.gems} gem` : ''}`;
    return `<button data-trial="${trial.id}" style="padding:14px;text-align:left;border:2px solid ${done ? '#4ade80' : '#8d6421'};border-radius:8px;background:rgba(42,18,10,.95);color:#f5e9c9;cursor:pointer;"><b style="display:block;color:#ffd770;">${index + 1}. ${trial.name} ${done ? '✓' : ''}</b><span style="display:block;margin-top:5px;font-size:12px;opacity:.8;">${trial.difficulty} · ${trial.labels.join(' → ')}</span><span style="display:block;margin-top:6px;color:#facc15;font-size:12px;">First clear: ${reward}</span></button>`;
  }).join('');
  wrap.innerHTML = `<section style="width:min(900px,calc(100vw - 32px));padding:24px;border:2px solid #c79b3a;border-radius:10px;background:rgba(20,12,6,.96);"><h2 style="margin:0;color:#ffd770;letter-spacing:.1em;">BILAL COMBO TRIALS</h2><p>${progress.completedCount()}/5 complete · Mastery ${progress.mastery('rickshaw_rider_bilal')} XP · Wallet ${economy.coins} coins / ${economy.gems} gems</p><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:10px;">${cards}</div><button data-back style="margin-top:16px;padding:9px 16px;border:2px solid #ffd770;border-radius:6px;background:#542313;color:#fff3b0;font-weight:900;cursor:pointer;">BACK</button></section>`;
  host.appendChild(wrap);
  wrap.querySelector('[data-back]').addEventListener('click', () => { wrap.remove(); onBack?.(); });
  for (const button of wrap.querySelectorAll('[data-trial]')) {
    button.addEventListener('click', () => {
      const trial = BILAL_TRIALS.find((item) => item.id === button.dataset.trial);
      wrap.remove();
      if (trial) onStart?.(trial);
    });
  }
  return wrap;
}
