import { MOVES } from '../../data/moves.js';

/**
 * ShoryukenState
 * --------------
 * Anti-air rising attack. Applies a strong upward velocity + slight
 * forward drift, plays a special clip, and exposes an active hitbox
 * during the ascent. On hit, the opponent is launched into the air.
 *
 * The uppercut has a short grounded wind-up, a protected rising window,
 * and a vulnerable landing recovery before the fighter can act again.
 *
 *   payload: { moveId: string }
 */
export const ShoryukenState = {
  name: 'shoryuken',

  enter(fighter, _prev, payload = {}) {
    const move = MOVES[payload.moveId] ?? MOVES.shoryuken_normal;
    this._move = move;
    this._frame = 0;
    this._hasHit = false;
    this._launched = false;
    this._landingFrame = null;
    this._nextTrailFrame = 0;

    fighter.velocity.x = 0;
    fighter.velocity.y = 0;
    // The initial frames beat a jump-in; the long landing remains punishable.
    fighter.invulnerabilityTimer = Math.max(
      fighter.invulnerabilityTimer ?? 0,
      Math.min(0.10, (move.startup ?? 4) / 60 + 0.025),
    );

    // Expose the active hitbox the resolver reads through Fighter.activeHitboxes.
    const self = this;
    fighter._currentAttack = {
      move,
      frame: 0,
      isActive: false,
      get hasHit() { return self._hasHit; },
    };

    fighter.playClip(move.animation ?? 'punch_medium', { loop: false, fade: 0.04 });
  },

  update(dt, _input, fighter) {
    this._frame += dt * 60;
    const m = this._move;
    const activeStart = m.startup ?? 4;
    const activeEnd = activeStart + (m.active ?? 14);

    if (!this._launched && this._frame >= activeStart) {
      this._launched = true;
      fighter.velocity.y = fighter.jumpVelocity * (m.launch?.selfY ?? 1.0);
      fighter.velocity.x = fighter.facing * (m.launch?.selfX ?? 0.35) * fighter.walkSpeed;
      fighter.isGrounded = false;
      fighter.onRisingLaunch?.(fighter, m);
    }
    if (this._launched && this._frame < activeEnd &&
        this._frame >= this._nextTrailFrame) {
      this._nextTrailFrame = this._frame + 4;
      fighter.onRisingTrail?.(fighter);
    }

    if (fighter._currentAttack) {
      fighter._currentAttack.frame = this._frame;
      fighter._currentAttack.isActive =
        this._frame >= activeStart && this._frame < activeEnd && !this._hasHit;
    }

    if (this._launched && fighter.isGrounded && this._landingFrame == null) {
      this._landingFrame = this._frame;
      fighter.velocity.x = 0;
    }
    const endFrame = Math.max(
      activeEnd + (m.recovery ?? 28),
      (this._landingFrame ?? Infinity) + 8,
    );
    if (this._landingFrame != null && this._frame >= endFrame) {
      return 'idle';
    }
    return null;
  },

  /** Called by combat resolver when the hit lands. */
  markHit(fighter) {
    this._hasHit = true;
    if (fighter && fighter._currentAttack) fighter._currentAttack.isActive = false;
  },

  exit(fighter) {
    fighter._currentAttack = null;
  },
};
