import { resolveAttackInput, resolveShoryukenInput, resolveSuperInput } from './_inputMaps.js';

export const DashState = {
  name: 'dash',

  enter(fighter, _prev, payload = {}) {
    this._elapsed = 0;
    this._backstep = !!payload.backstep;
    this._duration = this._backstep ? 0.25 : 0.19;
    this._direction = payload.direction ?? fighter.facing;
    const speed = fighter.walkSpeed * (this._backstep ? 2.5 : 3.15);
    fighter.velocity.x = this._direction * speed;
    fighter.invulnerabilityTimer = this._backstep ? 0.13 : 0;
    fighter.playClip(this._backstep ? 'walk_backward' : 'walk_forward', {
      loop: false,
      fade: 0.04,
      timeScale: this._backstep ? -2.1 : 2.35,
      fallbackNames: ['idle'],
    });
  },

  update(dt, input, fighter) {
    this._elapsed += dt;
    const progress = Math.min(1, this._elapsed / this._duration);
    fighter.velocity.x *= Math.max(0.65, 1 - progress * 0.25);

    if (!this._backstep && this._elapsed >= 0.065) {
      const superMove = resolveSuperInput(input, fighter);
      if (superMove) return { next: 'attack', payload: { moveId: superMove } };
      const dp = resolveShoryukenInput(input, fighter);
      if (dp) return { next: 'shoryuken', payload: { moveId: dp } };
      const attack = resolveAttackInput(input, fighter);
      if (attack) return { next: 'attack', payload: { moveId: attack } };
    }

    if (this._elapsed >= this._duration) return 'idle';
    return null;
  },

  exit(fighter) {
    fighter.velocity.x = 0;
  },
};
