import { MOVES } from '../../data/moves.js';
import { tunedNormalContactPose } from '../../data/contactPoseTuning.js';
import { resolveCancelInput } from './_inputMaps.js';

const MIN_ATTACK_ANIM_SCALE = 0.8;
const MAX_ATTACK_ANIM_SCALE = 4.2;
const DEFAULT_NORMAL_FADE = 0.02;

function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value));
}

// A move can mark the point in its source clip where the fist/foot reaches
// the opponent. Play the wind-up and follow-through at different rates so
// the gameplay active window opens on that visible contact pose.
export function contactPlayback(clipDuration, startTime, phaseFrames, contactFrames, contactPose) {
  if (!(clipDuration > 0) || !(contactFrames > 0) || contactFrames >= phaseFrames ||
      !(contactPose > 0 && contactPose < 1)) return null;
  const contactTime = clipDuration * contactPose;
  if (startTime >= contactTime) return null;
  const windupSeconds = contactFrames / 60;
  const followSeconds = (phaseFrames - contactFrames) / 60;
  // Skip excess anticipation in long imported clips instead of making a
  // four-frame jab race through its entire wind-up at an unreadable speed.
  const animationStart = Math.max(startTime, contactTime - windupSeconds * 2.7);
  return {
    animationStart,
    before: (contactTime - animationStart) / windupSeconds,
    after: clamp((clipDuration - contactTime) / followSeconds, 0.65, 3.2),
  };
}

function getAttackAnimOptions(fighter, move, animation, phaseFrames, contactFrames, contactPose) {
  const moveSeconds = Math.max(1 / 60, phaseFrames / 60);
  const clip = fighter.getClip?.(animation, move.animationFallbacks);
  const fitToMove = move.animationFit !== false;
  const maxScale = move.animationMaxScale ?? MAX_ATTACK_ANIM_SCALE;
  const fitScale = fitToMove && clip
    ? clamp(clip.duration / moveSeconds, MIN_ATTACK_ANIM_SCALE, MAX_ATTACK_ANIM_SCALE)
    : (move.animationTimeScale ?? 1);
  const timeScale = clamp(
    fitScale * (move.animationSpeedMultiplier ?? 1),
    MIN_ATTACK_ANIM_SCALE,
    maxScale,
  );

  const synced = contactPlayback(
    clip?.duration, move.animationStart ?? 0, phaseFrames, contactFrames, contactPose,
  );
  return {
    fade: move.animationFade ?? DEFAULT_NORMAL_FADE,
    timeScale: synced?.before ?? timeScale,
    animationStart: synced?.animationStart ?? move.animationStart ?? 0,
    fallbackNames: move.animationFallbacks ?? [],
    contactPlayback: synced,
  };
}

function playAttackPhase(fighter, move, phase, phaseFrames, contactFrames) {
  const crouchAnimation = `crouch_${phase.animation}`;
  const useCrouchClip = !!move.crouchAttack && !!fighter.getClip?.(crouchAnimation);
  const animation = useCrouchClip ? crouchAnimation : phase.animation;
  const options = getAttackAnimOptions(
    fighter, move, animation, phaseFrames, contactFrames,
    phase.contactPose ?? tunedNormalContactPose(
      fighter.character?.id, move.id, move.contactPose,
    ),
  );
  const { contactPlayback: timing, ...clipOptions } = options;
  fighter.playClip(animation, {
    loop: false,
    ...clipOptions,
    crouchBlend: useCrouchClip ? 0 : move.crouchBlend ?? 0,
  });
  return timing;
}

/**
 * AttackState
 * -----------
 * Plays one attack start-to-finish. Move data from moves.js drives the
 * frame timings (60 fps reference). The hitbox is "active" only inside
 * the active-frames window; before is startup, after is recovery.
 *
 * payload: { moveId: string }
 */
export const AttackState = {
  name: 'attack',

  enter(fighter, _prev, payload = {}) {
    const move = MOVES[payload.moveId] ?? MOVES.punch_light;
    this._move = move;
    this._frame = 0;
    this._total = (move.startup ?? 5) + (move.active ?? 3) + (move.recovery ?? 8);
    this._hasHit = false;
    this._phaseIndex = 0;

    // Live attack handle Fighter.activeHitboxes() reads from.
    // We use a getter so the state can flip hasHit after the resolver
    // calls markHit().
    const self = this;
    fighter._currentAttack = {
      move,
      frame: 0,
      isActive: false,
      get hasHit() { return self._hasHit; },
    };

    fighter.velocity.x = 0;
    fighter.forceVisualGrounding = !!move.crouchAttack || !!move.forceVisualGrounding ||
      !!move.groundToToes || (move.meterCost ?? 0) >= 100;
    fighter.forceToeGrounding = !!move.groundToToes;
    const phases = move.animationPhases;
    const first = phases?.[0] ?? { at: 0, animation: move.animation };
    this._phaseStart = first.at ?? 0;
    this._phaseTiming = playAttackPhase(
      fighter, move, first, phases?.[1]?.at ?? this._total,
      (move.startup ?? 0) - this._phaseStart,
    );
    fighter.startSuperProp?.(move);
    if ((move.meterCost ?? 0) >= 100) fighter.onSuperStartup?.(fighter, move);
    else if ((move.meterCost ?? 0) > 0) fighter.onSpecialStartup?.(fighter, move);
  },

  update(dt, _input, fighter) {
    this._frame += dt * 60;
    const m = this._move;
    const phases = m.animationPhases;
    while (phases?.[this._phaseIndex + 1] && this._frame >= phases[this._phaseIndex + 1].at) {
      this._phaseIndex++;
      const phase = phases[this._phaseIndex];
      const nextAt = phases[this._phaseIndex + 1]?.at ?? this._total;
      this._phaseStart = phase.at;
      this._phaseTiming = playAttackPhase(
        fighter, m, phase, nextAt - phase.at, (m.startup ?? 0) - phase.at,
      );
    }
    if (this._phaseTiming && fighter._currentAction &&
        this._frame >= (m.startup ?? 0)) {
      fighter._currentAction.timeScale = this._phaseTiming.after;
    }
    const movement = m.movement;
    if (movement?.type === 'dash_forward') {
      const start = movement.start ?? 0;
      const end = start + (movement.duration ?? 0);
      fighter.velocity.x = this._frame >= start && this._frame < end
        ? fighter.facing * movement.speed : 0;
    }
    const activeStart = m.startup ?? 0;
    const activeEnd = activeStart + (m.active ?? 0);

    if (fighter._currentAttack) {
      fighter._currentAttack.frame = this._frame;
      fighter._currentAttack.isActive =
        this._frame >= activeStart && this._frame < activeEnd && !this._hasHit;
    }

    const cancel = m.cancel;
    if (
      this._hasHit &&
      cancel &&
      this._frame >= cancel.start &&
      this._frame <= cancel.end
    ) {
      const next = resolveCancelInput(_input, fighter, cancel.actions);
      if (next) return { next: next.state, payload: { moveId: next.moveId } };
    }

    if (this._frame >= this._total) {
      return m.crouchAttack && _input.isDown?.('down', fighter.playerId) ? 'crouch' : 'idle';
    }
    return null;
  },

  /** Called by the combat resolver in main.js when this attack lands. */
  markHit(fighter) {
    this._hasHit = true;
    if (fighter && fighter._currentAttack) fighter._currentAttack.isActive = false;
  },

  exit(fighter, _next) {
    fighter._currentAttack = null;
    fighter.endSuperProp?.();
    if (this._move?.movement?.type === 'dash_forward') fighter.velocity.x = 0;
    if (this._move?.crouchAttack || this._move?.forceVisualGrounding ||
        this._move?.groundToToes || (this._move?.meterCost ?? 0) >= 100) {
      fighter.forceVisualGrounding = false;
      fighter.forceToeGrounding = false;
      fighter.visualOffsetY = 0;
    }
  },
};
