let _lastMonetizedMatchState = null;
let currentMatchConfig = null;
let postMatchPanel = null;
let flowMode = 'menu';
let championship = null;
const characterCueTimers = [];
const characterMomentAt = new Map();

function playCharacterMoment(character, cueName, phraseKey, side = 0, gain = 0.62) {
  const profile = character?.audioProfile;
  const soundId = profile?.funnySounds?.[cueName];
  if (!profile || !soundId) return;
  const played = synth.characterCue(soundId, {
    gain,
    pan: side === 0 ? -0.18 : 0.18,
  });
  if (!played) return;
  const phrase = profile[phraseKey];
  if (phrase) {
    showCombatCallout(`“${phrase}”`, side === 0 ? '#fff3b0' : '#b9e6ff', 920);
  }
}

function scheduleCharacterMoment(character, cueName, phraseKey, delayMs, side, gain) {
  const timer = setTimeout(
    () => playCharacterMoment(character, cueName, phraseKey, side, gain),
    delayMs,
  );
  characterCueTimers.push(timer);
}

function maybePlayCharacterMoment(fighter, cueName, phraseKey, cooldownMs, chance = 1) {
  if (!fighter?.character?.audioProfile || Math.random() > chance) return;
  const key = `${fighter.playerId}:${cueName}`;
  const now = Date.now();
  if (now - (characterMomentAt.get(key) ?? 0) < cooldownMs) return;
  characterMomentAt.set(key, now);
  playCharacterMoment(fighter.character, cueName, phraseKey, fighter.playerId, 0.48);
}

let _stageLoadPromise = null;
let _loadedStageId = null;
function getStagePromise(stageId = DEFAULT_STAGE_ID) {
  // If the requested stage matches what's already loaded, reuse the promise.
  if (_stageLoadPromise && _loadedStageId === stageId) return _stageLoadPromise;

  // Different stage requested: dispose old, build new.
  if (stage && stage.group) {
    sceneManager.scene.remove(stage.group);
  }

  const stageData = STAGES[stageId] ?? STAGES[DEFAULT_STAGE_ID];
  stage = new Stage(stageData, assetLoader);
  _loadedStageId = stageId;
  _stageLoadPromise = stage.load().then(() => {
    sceneManager.hidePlaceholderGround();
    sceneManager.scene.add(stage.group);
    stage.applyLighting(sceneManager.scene);
  });
  return _stageLoadPromise;
}

function hidePostMatchPanel() {
  if (postMatchPanel?.parentNode) postMatchPanel.parentNode.removeChild(postMatchPanel);
  postMatchPanel = null;
}

function clearCurrentMatch({ keepStage = true } = {}) {
  for (const timer of characterCueTimers.splice(0)) clearTimeout(timer);
  characterMomentAt.clear();
  hidePostMatchPanel();
  trainingSession?.dispose();
  trainingSession = null;
  document.getElementById('hud-root')?.remove();
  monetizationPanel.hide();
  projectiles?.clear?.();
  projectiles = null;
  combatPerformance = null;
  opponentAI = null;
  matchController = null;
  _lastMonetizedMatchState = null;
  for (const fighter of fighters.splice(0)) {
    fighter.endSuperProp?.();
    if (fighter?.rig?.parent) fighter.rig.parent.remove(fighter.rig);
  }
  if (!keepStage && stage?.group?.parent) {
    sceneManager.scene.remove(stage.group);
    stage = null;
    _stageLoadPromise = null;
    _loadedStageId = null;
  }
}

function getP2ModeForMatch(modeOverride) {
  return modeOverride || settings.get('p2Mode') || 'cpu_easy';
}

async function startMatch(p1Data, p2Data, stageId = DEFAULT_STAGE_ID, opts = {}) {
  try {
    clearCurrentMatch({ keepStage: true });
    pauseMenu.setMatchActive(false);
    if (opts.mode !== 'training') {
      const continueFight = await versusIntro.show({ p1: p1Data, p2: p2Data, stage: STAGES[stageId] ?? STAGES[DEFAULT_STAGE_ID] });
      if (!continueFight) return;
    }
    currentMatchConfig = { p1Data, p2Data, stageId, opts };
    synth.setStageMusic((STAGES[stageId] ?? STAGES[DEFAULT_STAGE_ID]).music);
    isSelectionMenuActive = false;
    applyTouchControlsFromSettings();
    setOverlay(`${BRANDING.displayName} · Loading fighters…`);

    const { p1: boxP1, p2: boxP2 } = sceneManager.placeholders;
    boxP1.visible = false;
    boxP2.visible = false;

    const [p1Asset, p2Asset] = await Promise.all([
      assetLoader.loadCharacter({
        url: p1Data.model,
        characterId: p1Data.id,
        animationMap: p1Data.animationMap,
        externalAnimations: p1Data.externalAnimations,
        animationLibrary: p1Data.animationLibrary,
        animationLibraryMap: p1Data.animationLibraryMap,
        crouchKickPose: p1Data.crouchKickPose,
      }),
      assetLoader.loadCharacter({
        url: p2Data.model,
        characterId: p2Data.id,
        animationMap: p2Data.animationMap,
        externalAnimations: p2Data.externalAnimations,
        animationLibrary: p2Data.animationLibrary,
        animationLibraryMap: p2Data.animationLibraryMap,
        crouchKickPose: p2Data.crouchKickPose,
      }),
      getStagePromise(stageId),
    ]);

    buildHud(p1Data, p2Data);

    const p1 = new Fighter({
      characterData: p1Data,
      asset: p1Asset,
      playerId: 0,
      facing: +1,
      spawn: { x: -1.6, y: 0 },
    });
    const p2 = new Fighter({
      characterData: p2Data,
      asset: p2Asset,
      playerId: 1,
      facing: -1,
      spawn: { x: 1.6, y: 0 },
    });
    sceneManager.scene.add(p1.rig);
    sceneManager.scene.add(p2.rig);
    fighters.push(p1, p2);
    for (const fighter of fighters) {
      fighter.onSuperUnavailable = (reason) => {
        if (fighter.playerId !== 0 && opponentAI) return;
        showCombatCallout(reason === 'meter'
          ? 'SUPER NEEDS A FULL GOLD METER'
          : 'SUPER UNAVAILABLE', '#ffe08a', 750);
      };
      fighter.onSpecialUnavailable = (reason) => {
        if (fighter.playerId !== 0 && opponentAI) return;
        showCombatCallout(reason === 'meter' ? 'SPECIAL NEEDS 25 METER' : 'SPECIAL UNAVAILABLE', '#d7b6ff', 700);
      };
      fighter.onSpecialStartup = (source, move) => {
        const point = new THREE.Vector3(source.position.x + source.facing * 0.34, 1.14, 0.06);
        juice.spawnHitSpark(point, move.impactColor ?? source.hadokenColor, 9, 0.55);
        showCombatCallout(move.name?.toUpperCase() ?? 'SPECIAL!', '#ead9ff', 500);
        maybePlayCharacterMoment(source, 'special', 'specialPhrase', 2600, 0.55);
      };
      fighter.onHadokenCharge = (source) => {
        const hand = new THREE.Vector3(
          source.position.x + source.facing * 0.34,
          source.position.y + 1.05,
          0.12,
        );
        juice.spawnHitSpark(hand, source.hadokenColor, 9, 0.3);
      };
      fighter.onSuperStartup = (source, move) => {
        const focus = new THREE.Vector3(source.position.x + source.facing * 0.25, 1.28, 0);
        const color = move.superColor ?? source.hadokenColor ?? 0xffd770;
        juice.cinematicFocus(focus, 0.84, 0.48);
        juice.spawnHitSpark(focus, color, 22, 0.8);
        juice.spawnSuperEffect(focus, color, move.superVfx, true);
        juice.shake(0.085, 0.25);
        juice.hitStop(0.055);
        showCombatCallout(move.name?.toUpperCase() ?? 'SUPER!', '#fff3b0', 650);
        maybePlayCharacterMoment(source, 'special', 'specialPhrase', 1600, 0.9);
      };
      fighter.onRisingLaunch = (source) => {
        const hand = new THREE.Vector3(
          source.position.x + source.facing * 0.24,
          source.position.y + 1.65,
          0.12,
        );
        juice.spawnHitSpark(hand, 0x69d9ff, 12, 0.8);
        synth.moveImpact('sfx_shoryuken');
      };
      fighter.onRisingTrail = (source) => {
        juice.spawnHitSpark(new THREE.Vector3(
          source.position.x + source.facing * 0.22,
          source.position.y + 1.5,
          0.12,
        ), 0x74dbff, 2, 0.25);
      };
      fighter.onThrowLand = (victim, move) => {
        const floor = new THREE.Vector3(victim.position.x, 0.08, 0.14);
        juice.spawnSuperEffect(floor, move.superColor ?? 0xffb347, 'heavy');
        juice.shake(0.12, 0.24);
        synth.moveImpact(move.fx?.sound ?? 'sfx_throw');
      };
    }
    combatPerformance = new CombatPerformance();
    if (import.meta.env.DEV && window.__dsf) {
      window.__dsf.combatPerformance = combatPerformance;
    }

    // Player 2 controller — driven by settings.p2Mode.
    //   'human'      → no AI; P2 reads keyboard (arrows + numpad) + Gamepad 2.
    //   'cpu_easy'   → AI on easy
    //   'cpu_medium' → AI on medium
    //   'cpu_hard'   → AI on hard
    const isTraining = opts.mode === 'training';
    const savedP2Mode = isTraining ? 'human' : getP2ModeForMatch(opts.p2Mode);
    const p2Mode = isNativeAndroid && savedP2Mode === 'human'
      && !isTraining ? 'cpu_easy'
      : savedP2Mode;
    if (p2Mode !== savedP2Mode) settings.set('p2Mode', p2Mode);
    if (p2Mode === 'human') {
      opponentAI = null;
      console.info('[boot] P2 = Human (keyboard / gamepad 2)');
    } else {
      const difficulty = p2Mode.startsWith('cpu_') ? p2Mode.slice(4) : 'easy';
      opponentAI = new AI({ self: p2, opponent: p1, difficulty });
      console.info(`[boot] P2 = CPU (${difficulty})`);
    }

    matchController = new MatchController({
      fighters,
      hud: { setBanner },
      onRoundStart: ({ round }) => {
        synth.roundCue();
        opponentAI?.beginRound(round);
        const side = round % 2 === 0 ? 1 : 0;
        const fighter = side === 0 ? p1Data : p2Data;
        scheduleCharacterMoment(fighter, 'taunt', 'petPhrase', 320, side, 0.54);
      },
      onRoundEnd: (roundResult) => combatPerformance?.recordRoundEnd(roundResult),
      practice: isTraining,
      onMatchEnd: (result) => {
        const playerWon = result.winnerIdx === 0;
        const performance = combatPerformance?.finish({
          playerIdx: 0,
          playerWon,
          roundsWon: result.roundsWon?.[0] ?? 0,
        });
        showPostMatchPanel({ ...result, performance });
      },
    });
    synth.roundCue();
    scheduleCharacterMoment(p1Data, 'intro', 'catchphrase', 260, 0, 0.68);
    scheduleCharacterMoment(p2Data, 'intro', 'catchphrase', 3300, 1, 0.68);
    if (import.meta.env.DEV && window.__dsf) {
      window.__dsf.matchController = matchController;
    }

    // Hadoken — wire projectile manager + scene ref into each fighter.
    projectiles = new ProjectileManager({
      scene: sceneManager.scene,
      onHit: (attacker, defender, move, fromX) => applyCombatHit(attacker, defender, move, fromX),
      onSpawn: (projectile) => {
        synth.projectileLaunch();
        juice.spawnHitSpark(new THREE.Vector3(projectile.position.x, projectile.position.y, 0.05),
          projectile.config.color, 7, 0.45);
      },
    });
    if (import.meta.env.DEV && window.__dsf) {
      window.__dsf.projectiles = projectiles;
    }
    p1._projectiles = projectiles;
    p2._projectiles = projectiles;
    p1._sceneRef = sceneManager.scene;
    p2._sceneRef = sceneManager.scene;

    if (isTraining && opts.trial) {
      trainingSession = new TrainingSession({
        host: uiRoot,
        trial: opts.trial,
        player: p1,
        dummy: p2,
        input,
        performance: combatPerformance,
        economy,
        progress: trainingProgress,
        onExit: showTrainingMenu,
        onEngagementEvent: recordDailyEvent,
      });
    }

    pauseMenu.setMatchActive(true);

    const cpuStyle = opponentAI ? ` · CPU: ${opponentAI.profile.name}` : '';
    const trainingStyle = isTraining ? ` · TRAINING: ${opts.trial.name}` : '';
    setOverlay(
      `<span class="match-title">${p1Data.name} vs ${p2Data.name}${cpuStyle}${trainingStyle}</span>` +
        '<span class="match-controls">Move A/D · Dash double-tap · Jump W · Crouch S/DN · Punch J/K/L · Kick U/I/O · Forward+L/HP overhead · Down+L/HP anti-air · Throw H · Special Space/SP (forward for rush) · Super G/SUP · Block ;</span>',
      'match-help',
    );
    console.info(`[boot] match started — ${p1Data.name} vs ${p2Data.name}`);
  } catch (err) {
    console.error('[boot] fighter load failed:', err);
    setOverlay(
      `${BRANDING.displayName} · LOAD ERROR<br>` +
        '<span style="font-size:11px;color:#ff8888;">' +
        String(err?.message ?? err) +
        '</span>',
    );
  }
}

