// ---- Combat resolver ------------------------------------------------------

function applyCombatHit(attacker, defender, sourceMove, fromX = attacker.position.x, hitRegion = null) {
  const attackerIdx = Math.max(0, Math.min(1, attacker.playerId ?? fighters.indexOf(attacker)));
  const hitsInMove = Math.max(1, Math.round(sourceMove.hits ?? 1));
  const damageScale = combatPerformance?.getDamageScale(attackerIdx, hitsInMove) ?? 1;
  const antiAirConnect = !!sourceMove.antiAir && !defender.isGrounded;
  const move = {
    ...sourceMove,
    damage: Math.max(1, Math.round((sourceMove.damage ?? 0) * damageScale * (antiAirConnect ? 1.2 : 1))),
    hitstun: (sourceMove.hitstun ?? 12) + (antiAirConnect ? 8 : 0),
  };
  const opportunity = combatOpportunity(defender);
  const isCounterHit = opportunity === 'counter';
  const isPunish = opportunity === 'punish';
  const isSuper = (move.meterCost ?? 0) >= 100 || move.animation === 'super_move';
  const wasAliveBefore = defender.hp > 0;
  const { blocked, damage, escaped } = defender.takeHit({
    move,
    fromX,
  });
  // Put the spark where the boxes actually intersect. A low sweep should not
  // burst at chest height, and a high punch should not flash at the feet.
  const overlap = hitRegion && {
    left: Math.max(hitRegion.hitbox.x, hitRegion.hurtbox.x),
    right: Math.min(hitRegion.hitbox.x + hitRegion.hitbox.w, hitRegion.hurtbox.x + hitRegion.hurtbox.w),
    bottom: Math.max(hitRegion.hitbox.y, hitRegion.hurtbox.y),
    top: Math.min(hitRegion.hitbox.y + hitRegion.hitbox.h, hitRegion.hurtbox.y + hitRegion.hurtbox.h),
  };
  const hitPos = new THREE.Vector3(
    overlap ? (overlap.left + overlap.right) / 2 : (attacker.position.x + defender.position.x) / 2,
    overlap ? (overlap.bottom + overlap.top) / 2 : (attacker.position.y + (move.hitbox?.y ?? 1.1)),
    0.05,
  );
  if (escaped) {
    const pushDirection = attacker.position.x <= defender.position.x ? -1 : 1;
    attacker.velocity.x = pushDirection * 2.0;
    juice.spawnHitSpark(hitPos, 0x67e8f9, 14, 1.1);
    juice.shake(0.055, 0.18);
    juice.hitStop(0.055);
    synth.block();
    showCombatCallout('THROW ESCAPE!', '#67e8f9', 680);
    if (defender.playerId === 0) recordDailyEvent('throw_escape');
    console.debug(`[throw escape] ${defender.character.name} escaped ${attacker.character.name}`);
    return;
  }
  if (trainingSession && attacker.playerId === 0 && defender.playerId === 1) {
    trainingSession.recordHit(move, { blocked });
  }
  attacker.gainSuperMeter?.((move.meterGain ?? 0) * (blocked ? 0.5 : 1));
  defender.gainSuperMeter?.(Math.min(14, Math.max(2, damage * 0.08)));
  const chain = combatPerformance?.recordHit({
    attackerIdx,
    damage,
    blocked,
    counter: isCounterHit && !blocked,
    punish: isPunish && !blocked,
    isSuper,
    isKO: wasAliveBefore && defender.hp <= 0,
    hits: hitsInMove,
  });
  if (attacker.playerId === 0 && !blocked && damage > 0) {
    recordDailyEvent('land_hits', { value: hitsInMove });
    recordDailyEvent('combo', { value: chain?.hits ?? hitsInMove });
    if (isSuper && wasAliveBefore && defender.hp <= 0) recordDailyEvent('super_finish');
  }
  console.debug(
    `[hit] ${attacker.character.name} -> ${defender.character.name}: ` +
      `${move.name ?? move.id} ${blocked ? '(blocked, chip ' : '('}${damage} dmg, ` +
      `scale ${damageScale.toFixed(2)}) ` +
      `HP ${defender.hp}/${defender.maxHp}`,
  );

  const dmg = move.damage ?? 0;
  const tier = dmg >= 100 ? 'heavy' : dmg >= 60 ? 'medium' : 'light';
  if (blocked) {
    juice.spawnHitSpark(hitPos, 0xb0c4d8, 6, 0.55);
    juice.shake(0.025, 0.12);
    juice.hitStop(0.035);
    synth.block();
  } else {
    const sparkColor = move.impactColor ?? move.superColor ?? (move.isShoryuken ? 0x69d9ff :
      tier === 'heavy' ? 0xff8a3a : tier === 'medium' ? 0xffd770 : 0xfff0c2);
    const sparkCount = isSuper ? 20 : move.id === 'hadoken' ? 14 : move.isShoryuken ? 15 :
      tier === 'heavy' ? 12 : tier === 'medium' ? 9 : 6;
    const sparkSpeed = tier === 'heavy' ? 1.4 : tier === 'medium' ? 1.1 : 0.9;
    juice.spawnHitSpark(hitPos, sparkColor, sparkCount, sparkSpeed);
    if (move.id === 'hadoken' || move.isShoryuken) flashImpact(55);
    const shakeAmp = tier === 'heavy' ? 0.10 : tier === 'medium' ? 0.055 : 0.025;
    const shakeDur = tier === 'heavy' ? 0.24 : tier === 'medium' ? 0.16 : 0.10;
    juice.shake(shakeAmp, shakeDur);
    const hitStopDuration = isSuper ? 0.135 : tier === 'heavy' ? 0.11 : tier === 'medium' ? 0.075 : 0.048;
    juice.hitStop(hitStopDuration);
    synth.hit(tier, move.fx?.sound);

    const isSignatureSound = move.fx?.sound && ![
      'sfx_hit_light',
      'sfx_hit_medium',
      'sfx_hit_heavy',
      'sfx_throw',
      'sfx_shoryuken',
    ].includes(move.fx.sound);
    if (isSignatureSound) {
      maybePlayCharacterMoment(attacker, 'special', 'specialPhrase', 3600, 1);
    } else if (tier !== 'light') {
      maybePlayCharacterMoment(defender, 'reaction', 'favoriteExpression', 4800, 0.18);
    }

    if (isCounterHit) {
      attacker.gainSuperMeter?.(5);
      juice.spawnHitSpark(hitPos, 0x67e8f9, 14, 1.25);
      showCombatCallout('COUNTER!', '#67e8f9', 560);
    }
    if (isPunish) {
      attacker.gainSuperMeter?.(5);
      juice.spawnHitSpark(hitPos, 0xffd770, 12, 1.05);
      showCombatCallout('PUNISH!', '#ffd770', 600);
    }
    if (antiAirConnect) showCombatCallout('ANTI-AIR!', '#8be9ff', 580);

    if (isSuper) {
      juice.spawnSuperEffect(hitPos, sparkColor, move.superVfx);
      juice.cinematicFocus(hitPos, 0.84, 0.48);
      juice.shake(0.14, 0.32);
      juice.slowMo(0.42, 0.18);
      flashImpact(120);
      showCombatCallout(move.name ?? 'SUPER!', '#fff3b0', 760);
    } else if (tier === 'heavy') {
      flashImpact(75);
    }

    if (wasAliveBefore && defender.hp <= 0) {
      juice.slowMo(0.75, 0.55);
      juice.shake(0.16, 0.38);
      juice.spawnHitSpark(hitPos, 0xffd770, 20, 1.4);
      synth.ko();
      playCharacterMoment(attacker.character, 'victory', 'victoryPhrase', attacker.playerId, 0.74);
    }
  }
}

function resolveDirectionalHit(attacker, defender) {
  if (!attacker._currentAttack) return;
  const result = Physics.resolveHits(attacker, defender);
  if (!result) return;
  const move = attacker._currentAttack.move;
  attacker.stateMachine.current?.markHit?.(attacker);
  applyCombatHit(attacker, defender, move, attacker.position.x, result);
}

function autoFaceOpponents() {
  if (fighters.length < 2) return;
  const [a, b] = fighters;
  const neutralA = a.stateMachine.currentName === 'idle' || a.stateMachine.currentName === 'walk';
  const neutralB = b.stateMachine.currentName === 'idle' || b.stateMachine.currentName === 'walk';
  if (neutralA) a.faceOpponent(b);
  if (neutralB) b.faceOpponent(a);
}

function updateMonetizationState() {
  const state = matchController?.state ?? null;
  if (state === _lastMonetizedMatchState) return;
  _lastMonetizedMatchState = state;

  if (state === 'round_intro' || state === 'fighting') {
    monetizationPanel.hide();
  }
}

// ---- Game loop ------------------------------------------------------------

const MAX_DT = 1 / 30;
let lastTime = performance.now();
let frameCount = 0;
let fpsAccumulator = 0;

const _wasGrounded = [true, true];

function frame(now) {
  const rawDt = (now - lastTime) / 1000;
  lastTime = now;
  const realDt = Math.min(rawDt, MAX_DT);
  const dt = realDt * juice.getDtScale();

  // Phase 12 — when paused, skip game logic but keep rendering the last frame.
  if (pauseMenu.isPaused()) {
    renderer.render(sceneManager.scene);
    requestAnimationFrame(frame);
    return;
  }

  // Phase 9 — poll gamepads before any game system reads input.
  input.pollGamepads();

  matchController?.update(dt);
  combatPerformance?.update(dt, fighters);
  updateMonetizationState();

  sceneManager.update(dt);
  stage?.update(dt);

  if (fighters.length === 2) {
    const p1WasLeft = fighters[0].position.x <= fighters[1].position.x;
    const locked = matchController ? matchController.isInputLocked() : false;
    opponentAI?.update(dt);
    trainingSession?.update(dt);
    const p1Input = locked ? matchController.noopInput : input;
    const p2Input = locked
      ? matchController.noopInput
      : (trainingSession ? trainingSession.dummyInput : (opponentAI ? opponentAI.input : input));
    fighters[0].update(dt, p1Input);
    fighters[1].update(dt, p2Input);
    if (matchController?.isCombatActive()) {
      Physics.resolveBodyOverlap(fighters[0], fighters[1], p1WasLeft);
    }

    for (let i = 0; i < 2; i++) {
      if (_wasGrounded[i] && !fighters[i].isGrounded &&
          fighters[i].stateMachine.currentName !== 'shoryuken') synth.jump();
      _wasGrounded[i] = fighters[i].isGrounded;
    }
  }

  if (matchController?.isCombatActive() && fighters.length === 2) {
    resolveDirectionalHit(fighters[0], fighters[1]);
    resolveDirectionalHit(fighters[1], fighters[0]);
  }

  autoFaceOpponents();
  projectiles?.update(dt, fighters);

  updateHud(fighters, matchController);
  touchControls.setSuperReady((fighters[0]?.superMeter ?? 0) >= 100);
  updateComboHud(combatPerformance);
  juice.update(realDt, Math.min(...fighters.map((fighter) => fighter.hp / fighter.maxHp), 1), fighters);
  renderer.render(sceneManager.scene);

  input.endFrame();
  opponentAI?.input.endFrame();
  trainingSession?.dummyInput.endFrame();

  fpsAccumulator += dt;
  frameCount += 1;
  if (fpsAccumulator >= 1) {
    const fps = Math.round(frameCount / fpsAccumulator);
    console.debug(`[boot] fps ≈ ${fps}`);
    fpsAccumulator = 0;
    frameCount = 0;
  }

  requestAnimationFrame(frame);
}

requestAnimationFrame((t) => {
  lastTime = t;
  frame(t);
});

