import { SyntheticInput } from '../engine/SyntheticInput.js';

const NORMAL_ATTACKS = [
  'punch_light', 'kick_light',
  'punch_medium', 'kick_medium',
  'punch_heavy', 'kick_heavy',
];

export const AI_DIFFICULTY = {
  easy: {
    reactionMs: 230, decisionRange: [0.5, 0.85], blockChance: 0.42,
    punishChance: 0.28, techChance: 0.2, comboDepth: 0, dashChance: 0.12,
    quickRiseDelay: 0.58, aimError: 0.24, postAttackPause: [0.3, 0.48],
  },
  medium: {
    reactionMs: 145, decisionRange: [0.28, 0.56], blockChance: 0.7,
    punishChance: 0.58, techChance: 0.5, comboDepth: 1, dashChance: 0.3,
    quickRiseDelay: 0.42, aimError: 0.12, postAttackPause: [0.16, 0.28],
  },
  hard: {
    reactionMs: 85, decisionRange: [0.16, 0.38], blockChance: 0.86,
    punishChance: 0.82, techChance: 0.72, comboDepth: 2, dashChance: 0.46,
    quickRiseDelay: 0.31, aimError: 0.05, postAttackPause: [0.05, 0.12],
  },
};

const BASE_PROFILE = {
  name: 'Balanced', preferredRange: 1.25, rangeTolerance: 0.28,
  aggression: 0.62, retreatChance: 0.18, throwChance: 0.12,
  heavyChance: 0.18, specialChance: 0.17, superChance: 0.42,
  fireballChance: 0.18, antiAirChance: 0.55, comebackBias: 0.14,
};

export const AI_PROFILES = {
  abdullah_sherdil: { ...BASE_PROFILE, name: 'Honour Guard', preferredRange: 1.3, specialChance: 0.24 },
  toofan_khan: {
    ...BASE_PROFILE, name: 'Qasai Pressure', preferredRange: 0.95,
    aggression: 0.82, retreatChance: 0.08, throwChance: 0.2,
    heavyChance: 0.32, specialChance: 0.3, comebackBias: 0.24,
  },
  aslam_karachiwala: {
    ...BASE_PROFILE, name: 'Street Rushdown', preferredRange: 0.9,
    aggression: 0.8, heavyChance: 0.1, specialChance: 0.1,
    throwChance: 0.16, comebackBias: 0.2,
  },
  sher_khan_afridi: {
    ...BASE_PROFILE, name: 'Patient Grappler', preferredRange: 0.72,
    aggression: 0.6, retreatChance: 0.08, throwChance: 0.46,
    heavyChance: 0.34, fireballChance: 0.05,
  },
  irfan_baloch: {
    ...BASE_PROFILE, name: 'Dakait Bait', preferredRange: 1.55,
    aggression: 0.52, retreatChance: 0.38, throwChance: 0.08,
    heavyChance: 0.12, fireballChance: 0.28, antiAirChance: 0.72,
  },
  dr_hina: {
    ...BASE_PROFILE, name: 'Clinical Counter', preferredRange: 1.45,
    aggression: 0.48, retreatChance: 0.34, throwChance: 0.1,
    heavyChance: 0.1, superChance: 0.58, antiAirChance: 0.78,
  },
  rickshaw_rider_bilal: {
    ...BASE_PROFILE, name: 'Cricket All-Rounder', preferredRange: 1.05,
    aggression: 0.76, retreatChance: 0.3, throwChance: 0.16,
    heavyChance: 0.08, specialChance: 0.32, antiAirChance: 0.7,
  },
  pehalwan_khan: {
    ...BASE_PROFILE, name: 'Akhara Grappler', preferredRange: 0.72,
    aggression: 0.58, retreatChance: 0.06, throwChance: 0.52,
    heavyChance: 0.42, specialChance: 0.3, fireballChance: 0.04,
  },
};

function clamp01(value) {
  return Math.max(0, Math.min(1, value));
}

/** Profile-driven CPU that emits the same actions used by human controls. */
export class AI {
  constructor({ self, opponent, difficulty = 'medium', random = Math.random }) {
    this.self = self;
    this.opponent = opponent;
    this.difficulty = difficulty;
    this.tuning = AI_DIFFICULTY[difficulty] ?? AI_DIFFICULTY.medium;
    this.profile = AI_PROFILES[self.character?.id] ?? BASE_PROFILE;
    this.random = random;
    this.input = new SyntheticInput();

    this._actionTimer = 0;
    this._heldAction = null;
    this._threatKey = null;
    this._threatTimerMs = 0;
    this._defenseRoll = 1;
    this._lastMoveId = null;
    this._lastObservedAttack = null;
    this._repeatCount = 0;
    this._lastMyState = self.stateMachine.currentName;
    this._quickRiseTimer = Infinity;
    this._comboRemaining = 0;
    this._roundPlan = null;
    this.beginRound(1);
  }

  beginRound(round = 1) {
    const plans = [
      { name: 'pressure', aggression: 0.12, range: -0.12 },
      { name: 'counter', aggression: -0.12, range: 0.2 },
      { name: 'grapple', aggression: 0.04, range: -0.24, throw: 0.14 },
    ];
    this._roundPlan = plans[Math.floor(this.random() * plans.length)];
    this._actionTimer = 0.12 + this.random() * 0.18;
    this._heldAction = null;
    this._threatKey = null;
    this._threatTimerMs = 0;
    this._lastMoveId = null;
    this._lastObservedAttack = null;
    this._repeatCount = 0;
    this._comboRemaining = 0;
    this.round = round;
  }

  update(dt) {
    const self = this.self;
    const opp = this.opponent;
    const myState = self.stateMachine.currentName;
    const oppState = opp.stateMachine.currentName;
    const distance = Math.abs(self.position.x - opp.position.x);
    const toward = opp.position.x > self.position.x ? 'right' : 'left';
    const away = toward === 'right' ? 'left' : 'right';
    const held = new Set();
    const pressed = new Set();

    this._actionTimer -= dt;
    this._observeState(myState);
    this._observeOpponentMove(oppState);

    if (myState === 'ko' || myState === 'hit' || myState === 'thrown') {
      return this._commit(held, pressed);
    }
    if (myState === 'knockdown') {
      this._quickRiseTimer -= dt;
      if (this._quickRiseTimer <= 0) {
        pressed.add('up');
        this._quickRiseTimer = Infinity;
      }
      return this._commit(held, pressed);
    }

    const threat = this._readThreat(distance, oppState);
    if (threat && this._defendAgainst(threat, dt, held, pressed)) {
      return this._commit(held, pressed);
    }

    if (myState === 'attack') {
      this._continueCombo(pressed);
      return this._commit(held, pressed);
    }
    if (myState === 'hadoken' || myState === 'shoryuken' || myState === 'jump') {
      return this._commit(held, pressed);
    }
    if (myState === 'block') return this._commit(held, pressed);

    if (this._actionTimer > 0) {
      if (this._heldAction) held.add(this._heldAction);
      return this._commit(held, pressed);
    }

    const hpRatio = self.hp / self.maxHp;
    const aggression = clamp01(
      this.profile.aggression +
      (this._roundPlan?.aggression ?? 0) +
      (hpRatio < 0.3 ? this.profile.comebackBias : 0),
    );
    const preferredRange = Math.max(
      0.62,
      this.profile.preferredRange +
      (this._roundPlan?.range ?? 0) +
      (this.random() - 0.5) * this.tuning.aimError,
    );
    const whiff = this._isWhiffPunishable(oppState);
    const opponentGuardsLow = oppState === 'crouch' ||
      (oppState === 'block' && !!opp.stateMachine.current?._low);

    if (!opp.isGrounded && distance < 1.65 && this.random() < this.profile.antiAirChance) {
      pressed.add('shoryuken');
      this._heldAction = null;
    } else if (opponentGuardsLow && distance < 1.35 && this.random() < 0.32) {
      held.add(toward);
      pressed.add('punch_heavy');
      this._heldAction = null;
    } else if (whiff && distance < 1.65 && this.random() < this.tuning.punishChance) {
      pressed.add(this._pickAttack({ punish: true }));
      this._startCombo();
      this._heldAction = null;
    } else if (distance > preferredRange + this.profile.rangeTolerance) {
      if (distance < 3.2 && self.superMeter >= 25 && self.character?.moves?.special_1 && this.random() < this.profile.specialChance * 0.65) {
        held.add(toward);
        pressed.add('special');
        this._heldAction = null;
      } else if (distance > 2.3 && self.hadokenCount > 0 && this.random() < this.profile.fireballChance) {
        pressed.add('hadoken');
        this._heldAction = null;
      } else if (this.random() < this.tuning.dashChance) {
        this.input.queueDoubleTap(toward);
        this._heldAction = null;
      } else {
        this._heldAction = toward;
      }
    } else if (distance < preferredRange - this.profile.rangeTolerance) {
      const throwChance = clamp01(this.profile.throwChance + (this._roundPlan?.throw ?? 0));
      if (distance < 0.95 && this.random() < throwChance) {
        pressed.add('throw');
        this._heldAction = null;
      } else if (this.random() < this.profile.retreatChance) {
        this.input.queueDoubleTap(away);
        this._heldAction = null;
      } else {
        pressed.add(this._pickAttack());
        this._startCombo();
        this._heldAction = null;
      }
    } else if (this.random() < aggression) {
      if (self.superMeter >= self.maxSuperMeter && this.random() < this.profile.superChance) {
        pressed.add('super');
      } else if (self.superMeter >= 25 && this._hasSpecial() && this.random() < this.profile.specialChance) {
        pressed.add('special');
      } else {
        pressed.add(this._pickAttack());
      }
      this._startCombo();
      this._heldAction = null;
    } else if (this.random() < this.profile.retreatChance) {
      this.input.queueDoubleTap(away);
      this._heldAction = null;
    } else {
      this._heldAction = this.random() < 0.5 ? toward : away;
    }

    const [lo, hi] = this.tuning.decisionRange;
    this._actionTimer = lo + this.random() * (hi - lo);
    if (this._heldAction) held.add(this._heldAction);
    return this._commit(held, pressed);
  }

  _observeState(myState) {
    if (myState === 'idle' && ['attack', 'shoryuken', 'hadoken'].includes(this._lastMyState)) {
      const [lo, hi] = this.tuning.postAttackPause;
      this._actionTimer = Math.max(this._actionTimer, lo + this.random() * (hi - lo));
      this._heldAction = null;
    }
    if (myState === 'knockdown' && this._lastMyState !== 'knockdown') {
      this._quickRiseTimer = this.tuning.quickRiseDelay + this.random() * 0.14;
    }
    this._lastMyState = myState;
  }

  _observeOpponentMove(oppState) {
    const moveId = oppState === 'attack' ? this.opponent._currentAttack?.move?.id : null;
    if (!moveId) {
      this._lastObservedAttack = null;
      return;
    }
    if (moveId === this._lastObservedAttack) return;
    this._lastObservedAttack = moveId;
    if (moveId === this._lastMoveId) this._repeatCount += 1;
    else {
      this._lastMoveId = moveId;
      this._repeatCount = 1;
    }
  }

  _readThreat(distance, oppState) {
    const attack = this.opponent._currentAttack;
    const move = attack?.move;
    const isAttack = oppState === 'attack' || oppState === 'shoryuken';
    const isProjectile = oppState === 'hadoken' && distance < 3.6;
    if ((!isAttack || !move) && !isProjectile) {
      this._threatKey = null;
      this._threatTimerMs = 0;
      return null;
    }
    const reach = move ? Math.max(1.05, (move.hitbox?.x ?? 0.5) + (move.hitbox?.w ?? 0.7)) : 3.6;
    if (!isProjectile && distance > reach + 0.38) {
      this._threatKey = null;
      this._threatTimerMs = 0;
      return null;
    }
    const activeEnd = (move?.startup ?? 0) + (move?.active ?? 0);
    if (!isProjectile && attack?.frame >= activeEnd) {
      this._threatKey = null;
      this._threatTimerMs = 0;
      return null;
    }
    const key = `${oppState}:${move?.id ?? 'projectile'}`;
    if (key !== this._threatKey) {
      this._threatKey = key;
      this._threatTimerMs = 0;
      this._defenseRoll = this.random();
    }
    return { isGrab: move?.hitLevel === 'grab', isLow: move?.hitLevel === 'low' };
  }

  _defendAgainst(threat, dt, held, pressed) {
    this._threatTimerMs += dt * 1000;
    const requiredReactionMs = threat.isGrab ? this.tuning.reactionMs * 0.72 : this.tuning.reactionMs;
    if (this._threatTimerMs < requiredReactionMs) return false;
    if (threat.isGrab) {
      if (this._defenseRoll < this.tuning.techChance) {
        pressed.add('throw');
        return true;
      }
      return false;
    }
    const spamBonus = this._repeatCount >= 3 ? 0.12 : 0;
    if (this._defenseRoll < clamp01(this.tuning.blockChance + spamBonus)) {
      held.add('block');
      if (threat.isLow) held.add('down');
      this._heldAction = null;
      return true;
    }
    return false;
  }

  _isWhiffPunishable(oppState) {
    if (oppState !== 'attack') return false;
    const attack = this.opponent._currentAttack;
    const move = attack?.move;
    if (!move || attack.hasHit) return false;
    return attack.frame >= (move.startup ?? 0) + (move.active ?? 0);
  }

  _startCombo() {
    this._comboRemaining = this.tuning.comboDepth;
  }

  _continueCombo(pressed) {
    const attack = this.self._currentAttack;
    const cancel = attack?.move?.cancel;
    if (!attack?.hasHit || !cancel || this._comboRemaining <= 0) return;
    if (attack.frame < cancel.start || attack.frame > cancel.end) return;
    const allowed = cancel.actions;
    let action = null;
    if (allowed.includes('super') && this.self.superMeter >= this.self.maxSuperMeter && this.random() < this.profile.superChance) {
      action = 'super';
    } else if (allowed.includes('special') && this.self.superMeter >= 25 && this._hasSpecial() && this.random() < this.profile.specialChance) {
      action = 'special';
    } else {
      const normals = allowed.filter((candidate) => NORMAL_ATTACKS.includes(candidate));
      action = normals[Math.floor(this.random() * normals.length)] ?? null;
    }
    if (action) {
      pressed.add(action);
      this._comboRemaining -= 1;
    }
  }

  _pickAttack({ punish = false } = {}) {
    const heavyChance = punish ? Math.min(0.7, this.profile.heavyChance + 0.22) : this.profile.heavyChance;
    const roll = this.random();
    if (roll < heavyChance) return this.random() < 0.5 ? 'punch_heavy' : 'kick_heavy';
    if (roll < heavyChance + 0.38) return this.random() < 0.5 ? 'punch_medium' : 'kick_medium';
    return this.random() < 0.5 ? 'punch_light' : 'kick_light';
  }

  _hasSpecial() {
    return ['special_1', 'special_2'].some((slot) => {
      const moveId = this.self.character?.moves?.[slot];
      return !!moveId && moveId !== 'tbd';
    });
  }

  _commit(held, pressed) {
    this.input.set(held, pressed);
    return this.input;
  }
}
