// New inline video reveals should appear once even for players who saw the old text-only intro.
const STORAGE_KEY = 'dsf.fighter-intros.v2';

export class FighterIntroProgress {
  constructor(storage) {
    try { this.storage = storage === undefined ? globalThis.localStorage : storage; }
    catch { this.storage = null; }
    this.seen = new Set();
    try {
      const saved = JSON.parse(this.storage?.getItem(STORAGE_KEY) ?? '[]');
      if (Array.isArray(saved)) this.seen = new Set(saved.filter((entry) => typeof entry === 'string'));
    } catch { /* Continue with in-memory progress if storage is unavailable. */ }
  }

  hasSeen(mode, fighterId) {
    return this.seen.has(`${mode}:${fighterId}`);
  }

  markSeen(mode, fighterId) {
    this.seen.add(`${mode}:${fighterId}`);
    try { this.storage?.setItem(STORAGE_KEY, JSON.stringify([...this.seen])); }
    catch { /* A private WebView can still play the intro once this session. */ }
  }
}
