import * as THREE from 'three';
import { AABB } from '../engine/Physics.js';
import { createHadokenAppearance, disposeHadokenAppearance } from './ProjectileAppearance.js';

/**
 * Projectile
 * ----------
 * A single fireball travelling along the X axis at constant speed.
 * Lives until it hits the opponent, collides with another projectile,
 * or its lifespan runs out.
 *
 *   const fb = new Projectile({
 *     owner: fighter,
 *     spawn: { x, y },
 *     facing: +1,
 *     config: { speed, damage, hitstun, chip, lifespan, color, radius },
 *     scene: sceneManager.scene,
 *   });
 */
export class Projectile {
  constructor({ owner, spawn, facing, config, scene }) {
    this.owner = owner;
    this.facing = facing;
    this.config = config;
    this.scene = scene;
    this.position = { x: spawn.x, y: spawn.y };
    this.age = 0;
    this.dead = false;
    this.hasHit = false;

    // Layer a bright center, energy arc, and fading echoes so the fireball
    // reads as a moving 3D attack instead of a single flat glow.
    const tex = Projectile._makeRadialTexture(config.color);
    const mat = new THREE.SpriteMaterial({
      map: tex,
      color: config.color,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      transparent: true,
      opacity: config.style ? 0.52 : 1,
    });
    this.sprite = new THREE.Sprite(mat);
    const d = config.radius * 2.2;
    this.sprite.scale.set(d, d, 1);
    this.sprite.position.set(this.position.x, this.position.y, 0.1);
    scene.add(this.sprite);

    this.core = new THREE.Sprite(new THREE.SpriteMaterial({
      map: tex,
      color: 0xffffff,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      transparent: true,
      opacity: config.style ? 0.34 : 0.88,
    }));
    this.core.scale.set(d * 0.47, d * 0.47, 1);
    this.core.position.set(this.position.x, this.position.y, 0.16);
    scene.add(this.core);

    this.arc = new THREE.Mesh(
      new THREE.TorusGeometry(config.radius * 1.15, config.radius * 0.13, 5, 30, Math.PI * 1.58),
      new THREE.MeshBasicMaterial({
        color: config.color,
        transparent: true,
        opacity: config.style ? 0.42 : 0.72,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
        side: THREE.DoubleSide,
      }),
    );
    this.arc.position.set(this.position.x, this.position.y, 0.13);
    scene.add(this.arc);

    this.appearance = createHadokenAppearance(config.style);
    if (this.appearance) {
      this.appearance.position.set(this.position.x, this.position.y, 0.26);
      this.appearance.scale.x = facing;
      scene.add(this.appearance);
    }

    // Trail — a short echo of fading sprites
    this._trail = [];
    for (let i = 0; i < 6; i++) {
      const t = new THREE.Sprite(mat.clone());
      t.scale.set(d * (1 - i * 0.12), d * (1 - i * 0.12), 1);
      t.material.opacity = 0.6 - i * 0.09;
      t.position.set(this.position.x, this.position.y, 0.1);
      scene.add(t);
      this._trail.push({ sprite: t, x: this.position.x, y: this.position.y });
    }
  }

  static _radialTexCache = new Map();
  static _makeRadialTexture(color) {
    if (Projectile._radialTexCache.has(color)) return Projectile._radialTexCache.get(color);
    const c = document.createElement('canvas');
    c.width = 128; c.height = 128;
    const ctx = c.getContext('2d');
    const g = ctx.createRadialGradient(64, 64, 6, 64, 64, 64);
    // White alpha texture takes its hue from the character's material color.
    g.addColorStop(0.0, 'rgba(255,255,255,1.0)');
    g.addColorStop(0.3, 'rgba(255,255,255,0.9)');
    g.addColorStop(0.6, 'rgba(255,255,255,0.5)');
    g.addColorStop(1.0, 'rgba(255,255,255,0.0)');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, 128, 128);
    const tex = new THREE.CanvasTexture(c);
    tex.colorSpace = THREE.SRGBColorSpace;
    Projectile._radialTexCache.set(color, tex);
    return tex;
  }

  update(dt) {
    this.age += dt;
    if (this.age > this.config.lifespan) {
      this.kill();
      return;
    }

    // Advance the trail one step
    for (let i = this._trail.length - 1; i > 0; i--) {
      this._trail[i].x = this._trail[i - 1].x;
      this._trail[i].y = this._trail[i - 1].y;
    }
    if (this._trail.length) {
      this._trail[0].x = this.position.x;
      this._trail[0].y = this.position.y;
    }

    this.position.x += this.config.speed * this.facing * dt;
    this.sprite.position.set(this.position.x, this.position.y, 0.1);
    this.core.position.set(this.position.x, this.position.y, 0.16);
    this.arc.position.set(this.position.x, this.position.y, 0.13);
    this.arc.rotation.z += this.facing * dt * 7;
    if (this.appearance) {
      this.appearance.position.set(this.position.x, this.position.y, 0.26);
      this.appearance.rotation.z += this.facing * dt * (this.config.style === 'syringe' ? 2.1 : 7.5);
    }
    const pulse = 1 + 0.09 * Math.sin(this.age * 27);
    this.sprite.scale.setScalar(this.config.radius * 2.2 * pulse);
    for (const t of this._trail) t.sprite.position.set(t.x, t.y, 0.1);

    // Off-stage cull
    if (Math.abs(this.position.x) > 9.5) this.kill();
  }

  /** AABB for collision tests this frame. */
  aabb() {
    const r = this.config.radius;
    return new AABB(this.position.x - r, this.position.y - r * 0.6, r * 2, r * 1.6);
  }

  /** Cancel both projectiles when they collide. */
  cancelWith(other) {
    this.kill();
    other.kill();
  }

  kill() {
    if (this.dead) return;
    this.dead = true;
    this.scene.remove(this.sprite);
    this.sprite.material.dispose();
    this.scene.remove(this.core);
    this.core.material.dispose();
    this.scene.remove(this.arc);
    this.arc.geometry.dispose();
    this.arc.material.dispose();
    if (this.appearance) {
      this.scene.remove(this.appearance);
      disposeHadokenAppearance(this.appearance);
      this.appearance = null;
    }
    for (const t of this._trail) {
      this.scene.remove(t.sprite);
      t.sprite.material.dispose();
    }
    this._trail = [];
  }
}
