import { Capacitor } from '@capacitor/core';
import { AdMob, MaxAdContentRating, RewardAdPluginEvents } from '@capacitor-community/admob';

const REWARD_AMOUNT = 50;
const REWARD_ITEM = 'Coins';

const TEST_ADS = Object.freeze({
  rewardedCoins: 'ca-app-pub-3940256099942544/5224354917',
  postMatchInterstitial: 'ca-app-pub-3940256099942544/1033173712',
});

const PRODUCTION_ADS = Object.freeze({
  appId: 'ca-app-pub-1797269464593835~8445832733',
  rewardedCoins: 'ca-app-pub-1797269464593835/1940125363',
  postMatchInterstitial: 'ca-app-pub-1797269464593835/7236859084',
});

// Only the dedicated Play release build can enable live ad units. Debug,
// story-review, and ordinary web builds always use Google's demo units.
const USE_LIVE_ADS = import.meta.env?.MODE === 'android-release';
const INTERSTITIAL_COOLDOWN_MS = 5 * 60 * 1000;
const FIRST_ELIGIBLE_MATCH = 3;
const MATCHES_BETWEEN_INTERSTITIALS = 2;

export class AdMobService {
  constructor({ adMob = AdMob, native = Capacitor.isNativePlatform(), clock = Date.now } = {}) {
    this._initialized = false;
    this._initializing = null;
    // Start the cooldown after an interstitial attempt, not at app launch.
    this._lastInterstitialAt = 0;
    this._completedMatches = 0;
    this._matchesSinceInterstitial = 0;
    this._native = native;
    this._adMob = adMob;
    this._clock = clock;
    this._rewardInFlight = false;
    this._adIds = USE_LIVE_ADS ? PRODUCTION_ADS : TEST_ADS;
  }

  get isNative() {
    return this._native;
  }

  get usingLiveAds() {
    return USE_LIVE_ADS;
  }

  get rewardAmount() {
    return REWARD_AMOUNT;
  }

  get rewardItem() {
    return REWARD_ITEM;
  }

  async initialize() {
    if (!this._native) {
      this._initialized = true;
      return { native: false, testing: true };
    }
    if (this._initialized) return { native: true, testing: !USE_LIVE_ADS };
    if (this._initializing) return this._initializing;

    this._initializing = (async () => {
      await this._adMob.initialize({
        initializeForTesting: !USE_LIVE_ADS,
        maxAdContentRating: MaxAdContentRating.Teen,
      });
      await this._adMob.setApplicationMuted({ muted: false });
      this._initialized = true;
      return { native: true, testing: !USE_LIVE_ADS };
    })().catch((err) => {
      this._initializing = null;
      console.warn('[ads] AdMob initialization failed', err);
      throw err;
    });

    return this._initializing;
  }

  async showRewardedCoins() {
    await this.initialize();

    if (!this._native) {
      return {
        amount: REWARD_AMOUNT,
        type: REWARD_ITEM,
        simulated: true,
      };
    }

    if (this._rewardInFlight) throw new Error('A rewarded ad is already open');
    this._rewardInFlight = true;
    const handles = [];
    try {
      const options = {
        adId: this._adIds.rewardedCoins,
        isTesting: !USE_LIVE_ADS,
        immersiveMode: true,
      };
      await this._adMob.prepareRewardVideoAd(options);
      let settleReward;
      const outcome = new Promise((resolve, reject) => {
        settleReward = { resolve, reject };
      });
      let settled = false;
      const earned = () => {
        if (settled) return;
        settled = true;
        // The game's reward is 50 coins even if AdMob's ad-unit reward item
        // is configured as "1 reward". The callback proves it was earned.
        settleReward.resolve({ amount: REWARD_AMOUNT, type: REWARD_ITEM, simulated: false });
      };
      const failed = (message) => {
        if (settled) return;
        settled = true;
        settleReward.reject(new Error(message));
      };
      handles.push(await this._adMob.addListener(RewardAdPluginEvents.Rewarded, earned));
      handles.push(await this._adMob.addListener(RewardAdPluginEvents.Dismissed,
        () => failed('Rewarded ad was closed before a reward was earned')));
      handles.push(await this._adMob.addListener(RewardAdPluginEvents.FailedToShow,
        () => failed('Rewarded ad could not be shown')));
      Promise.resolve(this._adMob.showRewardVideoAd()).then(earned,
        (err) => failed(err?.message ?? 'Rewarded ad failed'));
      return await outcome;
    } finally {
      await Promise.allSettled(handles.map((handle) => handle.remove()));
      this._rewardInFlight = false;
    }
  }

  async showPostMatchInterstitial({ canShow = () => true } = {}) {
    await this.initialize();

    this._completedMatches++;
    this._matchesSinceInterstitial++;
    const now = this._clock();
    if (!this._native) return { shown: false, reason: 'browser' };
    if (this._completedMatches < FIRST_ELIGIBLE_MATCH) {
      return { shown: false, reason: 'first-matches' };
    }
    if (this._matchesSinceInterstitial < MATCHES_BETWEEN_INTERSTITIALS) {
      return { shown: false, reason: 'match-spacing' };
    }
    if (now - this._lastInterstitialAt < INTERSTITIAL_COOLDOWN_MS) {
      return { shown: false, reason: 'cooldown' };
    }

    this._lastInterstitialAt = now;
    const options = {
      adId: this._adIds.postMatchInterstitial,
      isTesting: !USE_LIVE_ADS,
      immersiveMode: true,
    };
    await this._adMob.prepareInterstitial(options);
    if (!canShow()) return { shown: false, reason: 'match-left' };
    await this._adMob.showInterstitial();
    this._matchesSinceInterstitial = 0;
    return { shown: true };
  }
}

export const ADMOB_PRODUCTION_IDS = PRODUCTION_ADS;
