import { STAGE_BOUNDS } from '../engine/Physics.js';

/** Keep a caught fighter on the same side of the attacker and avoid an opening snap. */
export function planThrowPosition(attackerX, defenderX, separation = 1.05) {
  const min = STAGE_BOUNDS.minX + 0.55;
  const max = STAGE_BOUNDS.maxX - 0.55;
  const clamp = (x) => Math.max(min, Math.min(max, x));
  const direction = defenderX >= attackerX ? 1 : -1;
  const startX = clamp(defenderX);
  const targetX = clamp(direction > 0
    ? Math.max(startX, attackerX + separation)
    : Math.min(startX, attackerX - separation));
  return { startX, targetX };
}
