import { MOVES } from '../../data/moves.js';

/**
 * _inputMaps.js — Shared input -> move-id mapping for ground states.
 */
const ATTACK_BINDINGS = [
  ['punch_light', 'punch_light'],
  ['punch_medium', 'punch_medium'],
  ['punch_heavy', 'punch_heavy'],
  ['kick_light', 'kick_light'],
  ['kick_medium', 'kick_medium'],
  ['kick_heavy', 'kick_heavy'],
];

function consumeAction(input, action, playerId, withinMs = 160) {
  if (input.consumeBuffered) return input.consumeBuffered(action, playerId, withinMs);
  return input.wasPressed(action, playerId);
}

function spendMoveMeter(fighter, moveId) {
  const cost = MOVES[moveId]?.meterCost ?? 0;
  return fighter.trySpendSuperMeter?.(cost) ?? cost === 0;
}

function normalMoveId(input, fighter, baseId) {
  const pid = fighter.playerId;
  if (input.isDown?.('down', pid)) return `crouch_${baseId}`;
  const forward = fighter.facing === 1 ? 'right' : 'left';
  if (baseId === 'punch_heavy' && input.isDown?.(forward, pid)) {
    return 'overhead_punch';
  }
  return baseId;
}

function specialMoveId(input, fighter) {
  const forward = fighter.facing === 1 ? 'right' : 'left';
  const slot = input.isDown?.(forward, fighter.playerId) ? 'special_1' : 'special_2';
  const moveId = fighter.character?.moves?.[slot];
  return moveId && MOVES[moveId] ? moveId : null;
}

export function resolveAttackInput(input, fighter) {
  if (consumeAction(input, 'special', fighter.playerId)) {
    const specialMove = specialMoveId(input, fighter);
    if (specialMove && spendMoveMeter(fighter, specialMove)) {
      return specialMove;
    }
    fighter.onSpecialUnavailable?.(specialMove ? 'meter' : 'unavailable');
  }

  for (const [action, moveId] of ATTACK_BINDINGS) {
    if (consumeAction(input, action, fighter.playerId)) {
      return normalMoveId(input, fighter, moveId);
    }
  }
  return null;
}

export function resolveSuperInput(input, fighter) {
  if (!consumeAction(input, 'super', fighter.playerId)) return null;
  const moveId = fighter.character?.moves?.super_move;
  if (!moveId || moveId === 'tbd' || !MOVES[moveId]) {
    fighter.onSuperUnavailable?.('unavailable');
    return null;
  }
  if (!spendMoveMeter(fighter, moveId)) {
    fighter.onSuperUnavailable?.('meter');
    return null;
  }
  return moveId;
}

export function resolveBlockInput(input, fighter) {
  return input.isDown('block', fighter.playerId);
}

export function resolveDaavInput(input, fighter) {
  const pid = fighter.playerId;

  if (consumeAction(input, 'throw', pid)) {
    return fighter.character?.signatureDaav ?? 'daav_normal';
  }

  const lpPressed = input.wasPressed('punch_light', pid);
  const lkPressed = input.wasPressed('kick_light', pid);

  if (lpPressed && input.recentlyPressed?.('kick_light', pid, 80)) {
    input.consumeBuffered?.('punch_light', pid, 100);
    input.consumeBuffered?.('kick_light', pid, 100);
    return fighter.character?.signatureDaav ?? 'daav_normal';
  }
  if (lkPressed && input.recentlyPressed?.('punch_light', pid, 80)) {
    input.consumeBuffered?.('punch_light', pid, 100);
    input.consumeBuffered?.('kick_light', pid, 100);
    return fighter.character?.signatureDaav ?? 'daav_normal';
  }
  return null;
}

/**
 * Shoryuken — fired by either the dedicated button (B / Numpad 9) or by
 * DP motion (forward + down + heavy punch within ~280ms).
 */
export function resolveShoryukenInput(input, fighter) {
  const pid = fighter.playerId;

  if (consumeAction(input, 'shoryuken', pid)) {
    const moveId = fighter.character?.signatureShoryuken ?? 'shoryuken_normal';
    return spendMoveMeter(fighter, moveId) ? moveId : null;
  }

  if (!input.wasPressed('punch_heavy', pid)) return null;
  const forwardKey = fighter.facing === 1 ? 'right' : 'left';
  const sawForward = input.recentlyPressed?.(forwardKey, pid, 280);
  const sawDown    = input.recentlyPressed?.('down',     pid, 280);
  if (sawForward && sawDown) {
    const moveId = fighter.character?.signatureShoryuken ?? 'shoryuken_normal';
    return spendMoveMeter(fighter, moveId) ? moveId : null;
  }
  return null;
}

export function resolveDashInput(input, fighter) {
  if (!fighter.isGrounded || !input.consumeDoubleTap) return null;
  const forwardAction = fighter.facing === 1 ? 'right' : 'left';
  const backAction = fighter.facing === 1 ? 'left' : 'right';
  if (input.consumeDoubleTap(forwardAction, fighter.playerId, 240)) {
    return { direction: fighter.facing, backstep: false };
  }
  if (input.consumeDoubleTap(backAction, fighter.playerId, 240)) {
    return { direction: -fighter.facing, backstep: true };
  }
  return null;
}

export function resolveCancelInput(input, fighter, allowedActions = []) {
  const pid = fighter.playerId;
  for (const action of allowedActions) {
    if (action === 'special') {
      if (!consumeAction(input, action, pid)) continue;
      const moveId = specialMoveId(input, fighter);
      if (moveId && spendMoveMeter(fighter, moveId)) {
        return { state: 'attack', moveId };
      }
      fighter.onSpecialUnavailable?.(moveId ? 'meter' : 'unavailable');
      continue;
    }
    if (action === 'super') {
      if (!consumeAction(input, action, pid)) continue;
      const moveId = fighter.character?.moves?.super_move;
      if (moveId && moveId !== 'tbd' && MOVES[moveId] && spendMoveMeter(fighter, moveId)) {
        return { state: 'attack', moveId };
      }
      fighter.onSuperUnavailable?.(moveId && MOVES[moveId] ? 'meter' : 'unavailable');
      continue;
    }
    if (action === 'shoryuken') {
      if (!consumeAction(input, action, pid)) continue;
      const moveId = fighter.character?.signatureShoryuken ?? 'shoryuken_normal';
      if (spendMoveMeter(fighter, moveId)) return { state: 'shoryuken', moveId };
      continue;
    }
    const binding = ATTACK_BINDINGS.find(([boundAction]) => boundAction === action);
    if (binding && consumeAction(input, action, pid)) {
      return { state: 'attack', moveId: normalMoveId(input, fighter, binding[1]) };
    }
  }
  return null;
}
