// Imported combat clips reach forward at different points. These markers were
// measured from each fighter's hand/foot bones and checked in the animation
// viewer; they replace the shared marker only for standing normal attacks.
export const CONTACT_POSE_TUNING = Object.freeze({
  abdullah_sherdil: { punch_light: 0.56, kick_medium: 0.44 },
  toofan_khan: {
    punch_light: 0.22, punch_medium: 0.37, punch_heavy: 0.37,
    kick_light: 0.39,
  },
  aslam_karachiwala: { punch_light: 0.57, kick_medium: 0.44 },
  sher_khan_afridi: {
    punch_light: 0.37, punch_heavy: 0.31,
    kick_light: 0.36, kick_medium: 0.34, kick_heavy: 0.48,
  },
  irfan_baloch: { punch_light: 0.56, kick_medium: 0.44 },
  dr_hina: { punch_light: 0.56, kick_medium: 0.41 },
});

export function tunedNormalContactPose(characterId, moveId, fallback) {
  return CONTACT_POSE_TUNING[characterId]?.[moveId] ?? fallback;
}
