import { Capacitor, registerPlugin } from '@capacitor/core';

const PlayGames = registerPlugin('PlayGames');

const STORAGE_KEY = 'dsf.playGames.stats';

function loadStats() {
  try {
    return {
      totalWins: 0,
      quickFightWins: 0,
      championshipWins: 0,
      winStreak: 0,
      bestWinStreak: 0,
      ...JSON.parse(localStorage.getItem(STORAGE_KEY) || '{}'),
    };
  } catch {
    return {
      totalWins: 0,
      quickFightWins: 0,
      championshipWins: 0,
      winStreak: 0,
      bestWinStreak: 0,
    };
  }
}

function saveStats(stats) {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(stats));
  } catch {
    // Progress sync is best-effort. Gameplay must never fail because storage is blocked.
  }
}

export class PlayGamesService {
  constructor() {
    this._nativeAndroid = Capacitor.isNativePlatform() && Capacitor.getPlatform() === 'android';
    this._stats = loadStats();
  }

  get isAvailable() {
    return this._nativeAndroid;
  }

  async signIn() {
    if (!this._nativeAndroid) return { signedIn: false, native: false };
    return this._safeCall(() => PlayGames.signIn(), { signedIn: false, native: true });
  }

  async isSignedIn() {
    if (!this._nativeAndroid) return { signedIn: false, native: false };
    return this._safeCall(() => PlayGames.isSignedIn(), { signedIn: false, native: true });
  }

  async onChampionshipStarted() {
    await this._unlock('championship_started');
  }

  async onMatchComplete({ mode, playerWon, championshipComplete }) {
    if (playerWon) {
      this._stats.totalWins += 1;
      this._stats.winStreak += 1;
      this._stats.bestWinStreak = Math.max(this._stats.bestWinStreak, this._stats.winStreak);

      await this._unlock('first_win');
      if (this._stats.totalWins >= 5) await this._unlock('five_wins');
      if (this._stats.totalWins >= 10) await this._unlock('ten_wins');

      if (mode === 'quick') {
        this._stats.quickFightWins += 1;
        await this._submitScore('quick_fight_wins', this._stats.quickFightWins);
      }
    } else {
      this._stats.winStreak = 0;
    }

    if (mode === 'championship' && playerWon && championshipComplete) {
      this._stats.championshipWins += 1;
      await this._unlock('championship_clear');
      await this._submitScore('championship_wins', this._stats.championshipWins);
    }

    await this._submitScore('win_streak', this._stats.bestWinStreak);
    saveStats(this._stats);
  }

  async showAchievements() {
    if (!this._nativeAndroid) return;
    await this._safeCall(() => PlayGames.showAchievements());
  }

  async showLeaderboard(key) {
    if (!this._nativeAndroid) return;
    await this._safeCall(() => PlayGames.showLeaderboard({ key }));
  }

  async _unlock(key) {
    if (!this._nativeAndroid) return;
    await this._safeCall(() => PlayGames.unlockAchievement({ key }));
  }

  async _submitScore(key, score) {
    if (!this._nativeAndroid) return;
    await this._safeCall(() => PlayGames.submitScore({ key, score }));
  }

  async _safeCall(fn, fallback = undefined) {
    try {
      return await fn();
    } catch (err) {
      console.warn('[pgs] Play Games call skipped:', err?.message ?? err);
      return fallback;
    }
  }
}
