/** Classify a clean hit against an opponent committed to a move. */
export function combatOpportunity(defender) {
  const state = defender?.stateMachine?.currentName;
  if (state === 'attack' || state === 'shoryuken') {
    const attack = defender._currentAttack;
    if (attack) {
      const endOfActive = (attack.move.startup ?? 0) + (attack.move.active ?? 0);
      if (attack.frame >= endOfActive) return 'punish';
    }
    return 'counter';
  }
  return state === 'hadoken' ? 'counter' : null;
}
