import { STORY_CHAPTERS } from '../data/storyChapters.js';
import { youtubeEmbedUrl } from '../utils/youtubeEmbed.js';

const localStoryPreview = import.meta.env.MODE === 'story-qa';

export class FighterIntro {
  constructor(host) {
    this.host = host;
    this.root = null;
    this.video = null;
    this.keyHandler = null;
  }

  show({ fighter, mode, onContinue }) {
    this.hide();
    const chapter = STORY_CHAPTERS.find((entry) => entry.id === fighter.id && entry.group === 'Fighter reveals');
    const root = document.createElement('section');
    root.className = 'dsf-fighter-intro';
    root.setAttribute('role', 'dialog');
    root.setAttribute('aria-modal', 'true');
    root.setAttribute('aria-label', `${fighter.name} fighter story`);
    root.style.cssText = 'position:fixed;inset:0;z-index:90;pointer-events:auto;box-sizing:border-box;display:flex;align-items:center;justify-content:center;padding:max(8px,env(safe-area-inset-top)) max(8px,env(safe-area-inset-right)) max(8px,env(safe-area-inset-bottom)) max(8px,env(safe-area-inset-left));background:#090503ef;color:#f5e9c9;font-family:Segoe UI,system-ui,sans-serif';

    const panel = document.createElement('div');
    panel.style.cssText = 'box-sizing:border-box;width:min(900px,100%);max-height:100%;overflow-y:auto;overscroll-behavior:contain;touch-action:pan-y;-webkit-overflow-scrolling:touch;border:2px solid #c79b3a;border-radius:12px;background:linear-gradient(155deg,#27120a,#140b07);padding:clamp(10px,2vw,20px);box-shadow:0 16px 65px #000b';
    const header = document.createElement('header');
    header.style.cssText = 'position:sticky;top:0;z-index:2;display:flex;align-items:center;justify-content:space-between;gap:12px;margin:-2px -2px 10px;padding:2px 2px 8px;background:#27120a;border-bottom:1px solid #875f2c';
    const heading = document.createElement('div');
    const eyebrow = document.createElement('div');
    eyebrow.textContent = mode === 'championship' ? 'CHAMPIONSHIP · YOUR FIGHTER' : 'QUICK FIGHT · YOUR FIGHTER';
    eyebrow.style.cssText = 'color:#d4a743;font-size:clamp(10px,1.9vw,13px);font-weight:800;letter-spacing:.15em';
    const title = document.createElement('h2');
    title.textContent = fighter.name;
    title.style.cssText = 'margin:2px 0 0;color:#ffd770;font-size:clamp(19px,3vw,29px);line-height:1.1';
    heading.append(eyebrow, title);

    let completed = false;
    const continueFight = () => {
      if (completed) return;
      completed = true;
      this.hide();
      onContinue?.();
    };
    const skip = document.createElement('button');
    skip.type = 'button';
    skip.textContent = 'Skip intro · Fight';
    skip.style.cssText = 'flex:0 0 auto;min-height:44px;padding:8px 15px;border:2px solid #ffd770;border-radius:7px;background:#713019;color:#fff1c3;font:800 clamp(12px,2vw,16px) Segoe UI,system-ui,sans-serif;cursor:pointer';
    skip.addEventListener('click', continueFight);
    header.append(heading, skip);
    panel.appendChild(header);

    const content = document.createElement('div');
    content.style.cssText = 'display:flex;gap:clamp(10px,2vw,20px);align-items:center';
    const portrait = document.createElement('img');
    portrait.src = fighter.portrait;
    portrait.alt = fighter.name;
    portrait.style.cssText = 'width:clamp(70px,17vw,150px);max-height:23vh;object-fit:contain;border:1px solid #875f2c;border-radius:7px;background:#100907';
    portrait.onerror = () => { portrait.style.display = 'none'; };
    const text = document.createElement('div');
    text.style.cssText = 'min-width:0';
    const blurb = document.createElement('p');
    blurb.textContent = chapter?.blurb ?? fighter.tagline ?? '';
    blurb.style.cssText = 'margin:0 0 8px;color:#ffe0a0;font-size:clamp(13px,2.1vw,18px);font-weight:700';
    const story = document.createElement('p');
    story.textContent = fighter.backstory ?? '';
    story.style.cssText = 'margin:0;line-height:1.4;font-size:clamp(12px,1.7vw,15px)';
    text.append(blurb, story);
    content.append(portrait, text);
    panel.appendChild(content);

    if (localStoryPreview && chapter?.previewFile) {
      const video = document.createElement('video');
      video.controls = true;
      video.playsInline = true;
      video.preload = 'metadata';
      video.src = `${import.meta.env.MODE === 'story-qa' ? '/story-preview' : '/__story_preview'}/${chapter.previewFile}`;
      video.style.cssText = 'display:block;width:100%;max-height:32vh;margin-top:10px;background:#000;border-radius:5px';
      const note = document.createElement('p');
      note.textContent = 'The fight starts when the reveal ends. You can skip at any time.';
      note.style.cssText = 'margin:7px 0 0;color:#cdbf9d;font-size:12px';
      video.addEventListener('ended', continueFight);
      video.addEventListener('error', () => {
        note.textContent = 'Video unavailable. Tap Skip intro · Fight to continue.';
      });
      panel.append(video, note);
      this.video = video;
    } else if (youtubeEmbedUrl(chapter?.youtubeUrl)) {
      const frame = document.createElement('iframe');
      frame.src = youtubeEmbedUrl(chapter.youtubeUrl, { autoplay: true });
      frame.title = `${fighter.name} reveal video`;
      frame.allow = 'autoplay; encrypted-media; picture-in-picture; fullscreen';
      frame.allowFullscreen = true;
      frame.referrerPolicy = 'strict-origin-when-cross-origin';
      frame.style.cssText = 'display:block;width:100%;height:clamp(180px,32vh,320px);margin-top:10px;border:0;border-radius:5px;background:#000';
      panel.appendChild(frame);
    }

    root.appendChild(panel);
    this.host.appendChild(root);
    this.root = root;
    panel.scrollTop = 0;
    this.keyHandler = (event) => {
      if (event.key === 'Escape') {
        event.preventDefault();
        event.stopImmediatePropagation();
        continueFight();
      }
    };
    window.addEventListener('keydown', this.keyHandler, true);
    skip.focus();
    this.video?.play().catch(() => { /* The video controls remain available if autoplay is blocked. */ });
  }

  hide() {
    if (this.video) {
      this.video.pause();
      this.video.removeAttribute('src');
      this.video.load();
      this.video = null;
    }
    const frame = this.root?.querySelector('iframe');
    if (frame) frame.removeAttribute('src');
    if (this.keyHandler) window.removeEventListener('keydown', this.keyHandler, true);
    this.keyHandler = null;
    this.root?.remove();
    this.root = null;
  }
}
